window.MG_LAZY_DATA["data/lazy/owner-courses/b202-86f96d1501b6a0c7.json"]={sha256:"86f96d1501b6a0c7c60e21dc2949d6c5d5311d511f846af8fa11df26a2669a64",value:{"id":"b202","category":"water","kind":"course","status":"guided","contentStatus":"reviewable-educational-curriculum","depth":4,"languageCoverage":["zh-TW","en"],"sourceIds":["v6-hoover-history","v6-hoover-spillways","v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"],"stages":[{"id":"b202-stage01","order":1,"steps":[{"id":"b202-v6-01","sequence":1,"order":1,"sourceIds":["v6-hoover-history","v6-hoover-spillways"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":[],"title":"分開水庫、壩體與洩流路徑","titleEn":"Separate reservoir, dam and release paths","objective":"分辨擋水、蓄水、發電和溢洪功能。","objectiveEn":"Distinguish retention, storage, generation and spillway functions.","instruction":"自繪水庫、壩體、進水塔、壓力管、電廠及兩側溢洪路徑。以不同線型追蹤發電水路與溢洪水路到下游，標出它們與壩體的介面。","instructionEn":"Sketch reservoir, dam, intake towers, penstocks, powerhouse and side spillways. Trace generation and spillway routes to downstream using distinct line styles and mark dam interfaces.","observation":"確認溢洪水路並非越過壩頂流向電廠。","observationEn":"Confirm that the spillway route does not pass over the dam crest onto the powerhouse.","failure":"將所有放流水都畫成穿過水輪機，忽略獨立洩流功能。","failureEn":"Drawing all released water through turbines and overlooking separate release functions.","check":"圖中須有兩條可獨立追蹤的水路及各自功能。","checkEn":"Show two independently traceable water routes and their functions.","knowledge":[{"id":"b202-v6-01-k1","title":"功能分流","titleEn":"Functional separation","text":"蓄水結構與不同出流路徑共同構成水庫系統。","textEn":"The retaining structure and different outlet routes jointly form the reservoir system."},{"id":"b202-v6-01-k2","title":"介面辨識","titleEn":"Interface identification","text":"進水、管路、發電與下游水流的交界需要清楚定義。","textEn":"Interfaces among intakes, conduits, generation and downstream flow need clear definitions."}],"quiz":{"options":["溢洪道","水輪機壓力管，所有溢洪都必須經過它","壩頂道路，作為預定水流越頂路徑"],"optionsEn":["Spillway","Turbine penstocks, which all spill flow must use","The crest road as the intended overtopping route"],"answer":0,"question":"哪個構造最直接提供與發電水路分開的高水位洩流途徑？","questionEn":"Which structure most directly provides a high-water release path separate from generation?","explanation":"溢洪系統有獨立的水流路徑，不能以水輪機水路代替。","explanationEn":"The spillway has its own hydraulic path and cannot be represented by the turbine route."}},{"id":"b202-v6-02","sequence":2,"order":2,"sourceIds":["v6-hoover-history","v6-hoover-dam"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b202-v6-01"],"title":"追蹤拱壩與重力作用","titleEn":"Trace arch and gravity action","objective":"解釋壩體、基底與兩岸岩體如何共同受力。","objectiveEn":"Explain joint load transfer through dam body, base and canyon rock.","instruction":"畫平面與剖面兩張示意：平面標水壓與向兩岸傳力，剖面標自重、基底及水壓。註明這是厚拱壩的定性模型，不能用箭頭直接判定安全。","instructionEn":"Draw plan and section: show pressure and transfer toward abutments in plan, then weight, base and water pressure in section. Label this a qualitative thick-arch model, not a safety calculation.","observation":"觀察只畫剖面是否會遺漏兩岸岩體的作用。","observationEn":"Notice what abutment action is lost when only a section is drawn.","failure":"將壩的全部抵抗能力只歸因於重量或只歸因於拱形。","failureEn":"Attributing all resistance solely to weight or solely to curvature.","check":"兩張圖應共同包含水、壩體、基底和兩岸的力路徑。","checkEn":"Together, the sketches must include water, dam, base and abutment force paths.","knowledge":[{"id":"b202-v6-02-k1","title":"三維受力","titleEn":"Three-dimensional behavior","text":"厚拱壩的行為需同時考慮壩體與岩體支承，單一剖面不完整。","textEn":"A thick arch dam requires consideration of dam and rock support; one section is incomplete."},{"id":"b202-v6-02-k2","title":"邊界可靠性","titleEn":"Boundary reliability","text":"理想模型假設的支承能力需要地質與變形證據支持。","textEn":"Support capacity assumed in an ideal model needs geological and deformation evidence."}],"quiz":{"options":["兩岸只限制滲水，不參與傳力","拱作用把部分荷載傳入兩岸","拱形會使地基完全不受力"],"optionsEn":["Abutments only limit seepage and carry no structural load","Arch action transfers part of the load into the abutments","Curvature makes the foundation entirely unloaded"],"answer":1,"question":"兩岸岩體的條件為何影響拱作用判讀？","questionEn":"Why do abutment-rock conditions matter for arch action?","explanation":"受力路徑需要能承接反力的岩體邊界。","explanationEn":"The load path needs rock boundaries capable of providing reactions."}},{"id":"b202-v6-03","sequence":3,"order":3,"sourceIds":["v6-hoover-history"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b202-v6-02"],"title":"重建導流與乾地作業依賴","titleEn":"Reconstruct diversion dependencies","objective":"理解臨時導流如何提供永久工程的作業條件。","objectiveEn":"Understand how temporary diversion enables permanent works.","instruction":"依歷史資料畫出原河道、導流隧道與壩基作業區。用三格示意比較導流前、導流中和永久水路形成後，記錄每格水流去向。","instructionEn":"From historical accounts, sketch the river, diversion tunnels and foundation work area. Compare pre-diversion, diversion and permanent-waterway states, recording the flow destination in each.","observation":"檢查某一格是否意外把所有流路同時關閉。","observationEn":"Check whether a state inadvertently closes every flow route.","failure":"把圍堰視為不受來水影響的永久邊界，省略施工期洪水疑問。","failureEn":"Treating cofferdams as permanent, flow-independent boundaries and omitting construction-flood questions.","check":"每一格都保留連續水路及尚待專業分析的施工期風險。","checkEn":"Preserve a continuous water route and a construction-risk question in each state.","knowledge":[{"id":"b202-v6-03-k1","title":"臨時工程","titleEn":"Temporary works","text":"臨時設施的功能與失效會直接影響永久工程的施工條件。","textEn":"Temporary-work functions and failures directly affect conditions for permanent construction."},{"id":"b202-v6-03-k2","title":"狀態轉換","titleEn":"State transitions","text":"由導流到蓄水是系統邊界的變更，需要另行驗證。","textEn":"Transition from diversion to impoundment changes system boundaries and needs separate verification."}],"quiz":{"options":["尚未列出最後一台發電機的安裝日期","沒有先列出永久工程總材料量","某階段沒有說明來水可往何處流"],"optionsEn":["The last generator’s installation date is not yet given","Permanent-work material totals are not listed first","A stage gives no destination for incoming water"],"answer":2,"question":"在導流轉換圖中最嚴重的缺漏是什麼？","questionEn":"What is the most significant omission in a diversion-transition diagram?","explanation":"轉換階段仍須追蹤水流，不能因圖是中間狀態就忽略。","explanationEn":"Flow must remain accounted for even during an intermediate state."}},{"id":"b202-v6-04","sequence":4,"order":4,"sourceIds":["v6-hoover-dam"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b202-v6-03"],"title":"整理壩基與裂隙證據","titleEn":"Organize foundation and discontinuity evidence","objective":"分開岩石材料、接觸面與滲流路徑問題。","objectiveEn":"Separate rock-material, contact and seepage-path questions.","instruction":"在假想基岩剖面標記裂隙、壩基接觸面、排水與觀測位置。建立「材料強度」「接面狀態」「水壓」三欄，為每欄列出不同證據。","instructionEn":"On an invented rock section, mark discontinuities, dam contact, drains and observations. Create separate material-strength, contact-condition and water-pressure columns with distinct evidence needs.","observation":"注意堅硬岩石仍可能包含需要調查的裂隙與水路。","observationEn":"Recognize that strong rock may still contain discontinuities and water paths needing investigation.","failure":"只用岩石名稱或表面硬度，就認定壩基介面完整。","failureEn":"Declaring the foundation interface sound from rock name or surface hardness alone.","check":"三欄均須有觀察量與至少一項無法單獨推論的結論。","checkEn":"Give an observable and a conclusion it cannot establish alone in each column.","knowledge":[{"id":"b202-v6-04-k1","title":"岩體與岩塊","titleEn":"Rock mass versus intact rock","text":"岩塊性質不能完整代表含裂隙岩體的行為。","textEn":"Intact-rock properties do not fully describe a fractured rock mass."},{"id":"b202-v6-04-k2","title":"水壓與接觸","titleEn":"Water pressure and contact","text":"滲流條件會影響接觸面的有效受力，需與結構資料一起判讀。","textEn":"Seepage conditions affect effective contact loading and must be interpreted with structural evidence."}],"quiz":{"options":["該試體在試驗條件下的材料表現","整個壩基所有裂隙均不透水","任何水位下都不需監測"],"optionsEn":["Material behavior of that specimen under test conditions","Every foundation discontinuity is watertight","Monitoring is unnecessary at any reservoir level"],"answer":0,"question":"完整岩心強度良好，可直接證明什麼？","questionEn":"Good intact-core strength directly establishes what?","explanation":"試體證據有取樣與尺度範圍，不能無條件推廣到整個岩體。","explanationEn":"Specimen evidence has sampling and scale limits and cannot automatically represent the whole rock mass."}}],"title":"河谷與施工邊界","titleEn":"Canyon and construction boundaries","description":"分清永久工程的受力、水路與臨時導流。","descriptionEn":"Distinguish permanent load paths, water routes and temporary diversion."},{"id":"b202-stage02","order":2,"steps":[{"id":"b202-v6-05","sequence":5,"order":1,"sourceIds":["v6-hoover-history","v6-hoover-dam"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b202-v6-04"],"title":"閱讀分塊澆置的介面","titleEn":"Read block-construction interfaces","objective":"辨認分塊施工與最終整體作用的差別。","objectiveEn":"Distinguish block construction from final integrated behavior.","instruction":"把壩體畫成少量教學用方塊，標記不同完成高度與接縫。比較「單塊已有強度」和「相鄰區塊已形成設計傳力」兩種判斷所需的證據。","instructionEn":"Draw a few educational dam blocks with unequal completion heights and joints. Compare evidence for one block gaining strength with evidence for intended transfer between adjacent blocks.","observation":"觀察接縫狀態改變時，整體模型的連續性假設也需變更。","observationEn":"Notice how joint-state changes alter assumptions about structural continuity.","failure":"因所有塊體都已澆完，就視為接縫與整體作用自動完成。","failureEn":"Assuming joints and integrated action are complete because all blocks have been poured.","check":"標記每個示意接縫的狀態與尚缺驗證，避免填施工尺寸。","checkEn":"Mark each joint state and missing verification without assigning construction dimensions.","knowledge":[{"id":"b202-v6-05-k1","title":"分塊邏輯","titleEn":"Block logic","text":"分塊可管理施工與熱行為；最終整體作用仍須處理接縫。","textEn":"Blocks organize construction and thermal behavior; final integrated action still depends on joints."},{"id":"b202-v6-05-k2","title":"狀態紀錄","titleEn":"State records","text":"施工紀錄須能說明各區塊在同一時間的實際成熟與接合狀態。","textEn":"Records should identify each block’s maturity and connection state at a common time."}],"quiz":{"options":["以最後澆置日期代替所有接合驗證","接縫處理與整體傳力條件","以各塊外觀完整代替整體作用查證"],"optionsEn":["Use the last pour date in place of all joint verification","Joint treatment and conditions for integrated load transfer","Use intact block appearance as proof of integrated action"],"answer":1,"question":"所有壩塊已澆置，哪項仍須單獨查證？","questionEn":"All blocks are poured. What still requires independent verification?","explanation":"材料放置完成不等於所有介面功能完成。","explanationEn":"Completion of material placement does not establish completion of every interface function."}},{"id":"b202-v6-06","sequence":6,"order":2,"sourceIds":["v6-hoover-history","v6-hoover-dam"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b202-v6-05"],"title":"比較水化熱與冷卻歷程","titleEn":"Compare hydration heat and cooling histories","objective":"理解溫度梯度、收縮與裂縫的關係。","objectiveEn":"Understand relationships among thermal gradients, contraction and cracking.","instruction":"自繪混凝土核心與表面兩條溫度—時間曲線，再畫冷卻較快的比較曲線。標記水化放熱、散熱及相對收縮，不採用歷史設備數值作今日設定。","instructionEn":"Sketch core and surface temperature histories and a faster-cooling comparison. Mark hydration heat, heat loss and relative contraction without using historical equipment values as present settings.","observation":"比較最高溫相近但內外溫差不同的情況。","observationEn":"Compare cases with similar peak temperature but different internal-to-surface gradients.","failure":"把快速降溫一概當作越快越好，忽略拘束與梯度。","failureEn":"Assuming faster cooling is always better while ignoring restraint and gradients.","check":"解釋為何峰值、梯度與時間歷程都需保留。","checkEn":"Explain why peak, gradient and time history all need to be retained.","knowledge":[{"id":"b202-v6-06-k1","title":"熱源與尺度","titleEn":"Heat source and scale","text":"大體積混凝土的內部熱不易迅速逸散，溫度分布會不均勻。","textEn":"Heat within mass concrete does not escape quickly, producing nonuniform temperatures."},{"id":"b202-v6-06-k2","title":"拘束收縮","titleEn":"Restrained contraction","text":"自由收縮受到相鄰材料或幾何拘束時，可能產生應力。","textEn":"Contraction restrained by adjacent material or geometry can generate stress."}],"quiz":{"options":["是，最高溫是唯一需要的資料","只需表面溫度相同即可認定等效","不一定，梯度、拘束與材料歷程也影響結果"],"optionsEn":["Yes; peak temperature is the only relevant data","Equal surface temperature alone establishes equivalence","No; gradients, restraint and material history also matter"],"answer":2,"question":"相同最高溫的兩塊混凝土，裂縫風險必定相同嗎？","questionEn":"Do two concrete blocks with the same peak temperature necessarily share cracking risk?","explanation":"最高溫只描述熱歷程的一部分，無法取代梯度和拘束證據。","explanationEn":"Peak temperature captures only part of thermal history and cannot replace gradient and restraint evidence."}},{"id":"b202-v6-07","sequence":7,"order":3,"sourceIds":["v6-hoover-history","v6-hoover-dam"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b202-v6-06"],"title":"分清接縫灌漿與排水","titleEn":"Distinguish joint grouting from drainage","objective":"避免把填充接縫與降低滲流水壓混成同一功能。","objectiveEn":"Avoid conflating joint filling with management of seepage pressure.","instruction":"在兩張小圖分別畫壩塊接縫與壩基排水路徑。用功能敘述解釋灌漿、止水與排水各想改變什麼，再列出需查證的效果。","instructionEn":"Draw block joints and foundation drainage in separate sketches. Explain what grouting, water barriers and drainage seek to change, then identify evidence of their effects.","observation":"觀察流量減少是否同時需要查看水壓，而非單獨判為改善。","observationEn":"Check whether reduced flow also requires pressure data before it is called an improvement.","failure":"把排水孔流量變小直接認定為止水良好，忽略可能堵塞。","failureEn":"Treating falling drain flow as proof of improved water exclusion while overlooking possible blockage.","check":"提交功能對照與一組「流量下降」的兩種替代解釋。","checkEn":"Provide a function comparison and two alternative explanations for falling flow.","knowledge":[{"id":"b202-v6-07-k1","title":"功能區別","titleEn":"Different functions","text":"填充或接合、限制入流與引導排水，是不同工程功能。","textEn":"Filling or joining, limiting ingress and conveying drainage are different engineering functions."},{"id":"b202-v6-07-k2","title":"組合證據","titleEn":"Combined evidence","text":"流量與壓力一起看，比只看其中一項更能限制錯誤推論。","textEn":"Flow and pressure considered together constrain interpretations better than either alone."}],"quiz":{"options":["排水路徑受阻等替代原因","整體止水效果必然變好","只增加流量讀數次數，忽略壓力上升"],"optionsEn":["Alternative causes such as obstructed drainage","Water exclusion has necessarily improved","Repeat flow readings while ignoring rising pressure"],"answer":0,"question":"排水流量下降而附近水壓升高，應優先考慮什麼？","questionEn":"Drain flow falls while nearby water pressure rises. What warrants consideration?","explanation":"相反的水壓與流量趨勢不能只解讀為漏水減少。","explanationEn":"Opposing pressure and flow trends cannot be interpreted solely as reduced leakage."}},{"id":"b202-v6-08","sequence":8,"order":4,"sourceIds":["v6-hoover-history"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b202-v6-07"],"title":"連結進水、管路與水輪機","titleEn":"Link intake, conduit and turbine interfaces","objective":"辨識高程差、流量與瞬變的不同問題。","objectiveEn":"Distinguish head, flow and transient-response questions.","instruction":"自繪水面、進水口、壓力管和水輪機的高程關係。用兩格比較穩定流動與流量改變的概念，註明沒有進行真實閥門操作或壓力計算。","instructionEn":"Sketch elevations of reservoir surface, intake, penstock and turbine. Compare steady flow and changing flow in two panels, explicitly excluding real valve operation or pressure calculations.","observation":"注意管路不是只把水運送到機組，也承受壓力與約束反力。","observationEn":"A conduit transports water while also carrying pressure and restraint forces.","failure":"只用高程差估算發電概念，就宣稱已驗證管路所有受力。","failureEn":"Claiming complete conduit verification from an elevation-based generation estimate alone.","check":"列出穩態與瞬變各需的資料，並保留未知邊界條件。","checkEn":"List data needed for steady and transient states, keeping unknown boundary conditions explicit.","knowledge":[{"id":"b202-v6-08-k1","title":"能量路徑","titleEn":"Energy path","text":"水位差提供能量潛力；實際輸出還受流量與損失影響。","textEn":"Water-level difference provides energy potential; output also depends on flow and losses."},{"id":"b202-v6-08-k2","title":"瞬變效應","titleEn":"Transient effects","text":"流速改變會引起隨時間變化的壓力，不能只用穩態圖描述。","textEn":"Changing velocity produces time-varying pressure that a steady-state diagram cannot fully describe."}],"quiz":{"options":["穩態平均壓力必定等於所有瞬時峰值","流量變化可能造成動態壓力反應","只要高程不變，壓力就不可能隨時間變化"],"optionsEn":["Steady mean pressure necessarily equals every transient peak","Changing flow can create a dynamic pressure response","If elevation stays fixed, pressure cannot change with time"],"answer":1,"question":"為何穩態壓力資料不能單獨代表快速流量變化時的狀態？","questionEn":"Why cannot steady pressure alone represent a rapid flow change?","explanation":"瞬變是時間相關的系統反應，需要額外的模型及資料。","explanationEn":"A transient is a time-dependent system response requiring additional modeling and evidence."}}],"title":"壩體與水工介面","titleEn":"Dam body and hydraulic interfaces","description":"追蹤分塊、熱變形、接縫與管路的相互影響。","descriptionEn":"Trace interactions among blocks, thermal movement, joints and conduits."},{"id":"b202-stage03","order":3,"steps":[{"id":"b202-v6-09","sequence":9,"order":1,"sourceIds":["v6-hoover-spillways"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b202-v6-08"],"title":"從溢洪道侵蝕追查水流","titleEn":"Trace spillway erosion to flow behavior","objective":"區分看到的損傷與尚未確定的侵蝕機制。","objectiveEn":"Separate observed damage from an unconfirmed erosion mechanism.","instruction":"依歷史案例自繪溢洪道至斜隧道的路徑，在一處標示假想侵蝕。列出流路幾何、接縫、流量歷程與表面調查等需查證資料，不直接指定修補材料。","instructionEn":"Sketch the historical spillway-to-inclined-tunnel path and mark hypothetical erosion. List geometry, joints, flow history and surface evidence to investigate without prescribing repair materials.","observation":"比較同樣「混凝土缺損」可能具有不同位置、發展速度及成因。","observationEn":"Similar concrete loss may differ in location, growth rate and cause.","failure":"看見侵蝕就套用單一成因，或把修補完成當成成因已排除。","failureEn":"Assigning one cause from appearance or treating a completed repair as proof the cause is removed.","check":"建立損傷地圖，明確分出已觀察事實與待驗證機制。","checkEn":"Create a damage map distinguishing observed facts from mechanisms requiring verification.","knowledge":[{"id":"b202-v6-09-k1","title":"水工損傷","titleEn":"Hydraulic damage","text":"高速水流與局部幾何可能形成複雜作用；外觀不足以單獨辨因。","textEn":"High-speed flow and local geometry can interact in complex ways; appearance alone is insufficient for diagnosis."},{"id":"b202-v6-09-k2","title":"歷史回饋","titleEn":"Historical feedback","text":"既有侵蝕與修復紀錄提供檢查重點，但不能直接代替新事件調查。","textEn":"Historical erosion and repairs guide inspection but do not replace investigation of a new event."}],"quiz":{"options":["只核對修補材料強度，不檢查流路","沿用前次成因，不核對本次事件條件","事件流量歷程、幾何和局部表面狀態"],"optionsEn":["Check repair strength without examining the water route","Reuse the previous diagnosis without checking this event","Event flow history, geometry and local surface conditions"],"answer":2,"question":"修補區再次出現侵蝕，最應補查哪類證據？","questionEn":"Erosion reappears near a repair. What evidence most needs review?","explanation":"反覆損傷需要回到水流與局部介面的機制，而非只記錄修補外觀。","explanationEn":"Repeated damage requires review of flow and interface mechanisms, not only repaired appearance."}},{"id":"b202-v6-10","sequence":10,"order":2,"sourceIds":["v6-hoover-history","v6-hoover-dam"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b202-v6-09"],"title":"建立壩體監測比較窗","titleEn":"Establish comparable dam-monitoring windows","objective":"把水位、溫度與變形的時間關係分開。","objectiveEn":"Separate time relationships among reservoir level, temperature and deformation.","instruction":"自行製作六列示例水位、氣溫、位移與排水紀錄，標記季節性變化。挑出兩組相近條件資料，比較剩餘差異並保留儀器核對欄。","instructionEn":"Invent six records of reservoir level, temperature, movement and drainage, marking seasonal variation. Compare two matched-condition groups and retain an instrument-check field.","observation":"觀察同一位移數字可能對應不同水位或溫度狀態。","observationEn":"The same displacement value may occur under different water-level or temperature conditions.","failure":"把正常環境循環或感測器零點變更直接當成永久損傷。","failureEn":"Treating environmental cycles or sensor-zero changes as permanent damage.","check":"為一個異常保留環境、儀器與結構三種可能解釋。","checkEn":"Retain environmental, instrument and structural explanations for one anomaly.","knowledge":[{"id":"b202-v6-10-k1","title":"條件化比較","titleEn":"Conditional comparison","text":"跨時比較應記錄荷載與環境，避免將不同條件混成趨勢。","textEn":"Comparisons over time should retain load and environment rather than merge different conditions into one trend."},{"id":"b202-v6-10-k2","title":"證據交叉核對","titleEn":"Cross-checking evidence","text":"位移、滲流和目視紀錄各有盲點，組合使用有助限制誤判。","textEn":"Movement, seepage and visual records have different blind spots; combining them limits misinterpretation."}],"quiz":{"options":["有需要進一步檢驗的相關性","已證明全部由溫度造成","已證明壩體永久失效"],"optionsEn":["A correlation requiring further examination","Temperature has been proven the sole cause","Permanent dam failure has been proven"],"answer":0,"question":"位移季節性變化與氣溫同步，能直接推論什麼？","questionEn":"Displacement varies seasonally with temperature. What can be inferred directly?","explanation":"同步變化是線索，並非單獨的因果或安全證明。","explanationEn":"Synchronous variation is a clue, not standalone causal or safety proof."}},{"id":"b202-v6-11","sequence":11,"order":3,"sourceIds":["v6-hoover-history","v6-hoover-spillways"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b202-v6-10"],"title":"做有邊界的水量收支","titleEn":"Construct a bounded water balance","objective":"區分蓄水變化與不同出流用途。","objectiveEn":"Distinguish storage change from different outflow uses.","instruction":"自設一個單日水量例子，列入入流、放流、蒸發與蓄水變化。再畫兩個不同放流分配的教學情境，只比較質量守恆，不提出真實調度建議。","instructionEn":"Invent a one-day example with inflow, release, evaporation and storage change. Compare two illustrative release allocations for mass balance only, without recommending real reservoir operations.","observation":"檢查發電流量與總放流是否被重複計入。","observationEn":"Check whether generation flow is double-counted within total release.","failure":"將通過水輪機的水當成消失，或忽略水庫蓄積。","failureEn":"Treating turbine flow as consumed water or omitting storage change.","check":"收支需閉合，並標明全部數字是自設例子及尚缺用途限制。","checkEn":"Close the balance and label all numbers as invented, with unmodeled use constraints.","knowledge":[{"id":"b202-v6-11-k1","title":"守恆邊界","titleEn":"Conservation boundary","text":"在選定空間與時間內，水量入出與蓄積必須一致。","textEn":"Within defined space and time, inflow, outflow and storage must balance."},{"id":"b202-v6-11-k2","title":"多重目標","titleEn":"Multiple objectives","text":"供水、發電、洪水與環境問題不會被單一水量平衡自動解決。","textEn":"A water balance alone does not resolve supply, energy, flood and environmental objectives."}],"quiz":{"options":["同時列為兩次出流","作為出流，不再另列一次消耗","從所有收支欄刪除"],"optionsEn":["As two separate outflows","As outflow, without counting a second consumption","Omit it from the balance"],"answer":1,"question":"水流經水輪機後到達下游，在水庫收支中應如何處理？","questionEn":"Water passes through turbines to downstream. How is it represented in the reservoir balance?","explanation":"同一水量不能因用途名稱不同而重複計算。","explanationEn":"The same water must not be counted twice because it has different use labels."}},{"id":"b202-v6-12","sequence":12,"order":4,"sourceIds":["v6-hoover-history","v6-hoover-dam","v6-hoover-spillways"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b202-v6-11"],"title":"編成壩工證據與限制清單","titleEn":"Compile dam-engineering evidence and limits","objective":"交付能區分歷史案例、模型與實測需求的資料。","objectiveEn":"Deliver records distinguishing historical cases, models and measurement needs.","instruction":"整理水路圖、受力圖、施工狀態、熱曲線與監測表。為每項結論註記它屬歷史事實、教學假設或仍需實測，並列出專業複核邊界。","instructionEn":"Organize route, force, construction-state, thermal and monitoring records. Label each conclusion as historical fact, educational assumption or needing measurement, and identify professional-review boundaries.","observation":"核對舊施工記錄是否被誤寫成現行通用規格。","observationEn":"Check whether a historical construction record has been misrepresented as a current universal specification.","failure":"把課程示意數值寫入真實施工、設備或放流水量設定。","failureEn":"Transferring illustrative course values into actual construction, equipment or release settings.","check":"至少五項判斷可回查到來源或自設假設，未解問題單獨列出。","checkEn":"Make at least five conclusions traceable to sources or declared assumptions, with open issues listed separately.","knowledge":[{"id":"b202-v6-12-k1","title":"歷史與規範","titleEn":"History versus specifications","text":"歷史工程能提供思考案例，但今日設計需另外的資料與程序。","textEn":"Historical engineering provides cases for reasoning; present design requires additional evidence and procedures."},{"id":"b202-v6-12-k2","title":"範圍宣告","titleEn":"Scope declaration","text":"證據能支持什麼及不能支持什麼，都應出現在交付中。","textEn":"A handover should state both what evidence supports and what it does not."}],"quiz":{"options":["已完成課程，所以真壩可按此圖操作","歷史數字可直接套用任何新壩","本模型展示功能與依賴，尚非壩體安全鑑定"],"optionsEn":["Course completion authorizes operation from this sketch","Historical values apply directly to any new dam","This model shows functions and dependencies, not a dam-safety assessment"],"answer":2,"question":"哪項交付敘述最合適？","questionEn":"Which handover statement is most appropriate?","explanation":"學習模型的可審查性不等於真實工程驗證完成。","explanationEn":"A reviewable learning model is not completed validation of a real engineering system."}}],"title":"洩流與長期判讀","titleEn":"Releases and long-term interpretation","description":"以侵蝕、監測與水量證據檢查工程的運作邊界。","descriptionEn":"Review operating boundaries using erosion, monitoring and water-balance evidence."},{"id":"b202-v15-s1","title":"水文條件、邊界與工程系統","titleEn":"Hydrology, boundaries and engineering system","description":"本階段聚焦「拱座相容與分力」與「裂縫連通與揚壓」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Abutment compatibility and load sharing\" and \"Crack connectivity and uplift\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b202-v15-01","title":"拱座相容與分力：機制與系統路徑","titleEn":"Abutment compatibility and load sharing: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"],"prerequisiteIds":["b202-v6-12"],"objective":"說明「拱座相容與分力」如何影響胡佛壩的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Abutment compatibility and load sharing” governs forces, deformation, flow or signals in “Hoover Dam”, and map the relevant inputs, transfer paths and boundaries.","instruction":"拱重力壩把一部分水平荷載沿拱圈送到兩岸，也把一部分荷載透過壩底傳入基礎。教材以同位移的平行彈簧理解剛度與分力，不把它當成真實拱壩公式。岩體節理、施工縫及溫度會改變相容條件，所以增加某路徑剛度也會改變其他路徑分擔。 平行彈簧共同位移來自相容條件，若兩岸支承本身移動，需把支承位移加入，分力比例就不再只由剛度決定。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「拱座相容與分力」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"An arch-gravity dam transfers some horizontal load toward the abutments and some through its base. Parallel springs with equal displacement illustrate stiffness-controlled sharing, not a real arch-dam design equation. Rock joints, construction joints and temperature alter compatibility, so stiffening one path changes the load carried by the other path as well. Equal spring displacement follows compatibility; moving supports introduce imposed displacements, after which stiffness ratios alone no longer determine the force shares between the paths. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Abutment compatibility and load sharing” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，輸入均非本工程操作參數：ka=8 GN/m; kg=12 GN/m; F=100 MN; Fa=F*ka/(ka+kg)=40 MN。","observationEn":"Order-of-magnitude cue: Original hypothetical example; inputs are not operating parameters of this project: ka=8 GN/m; kg=12 GN/m; F=100 MN; Fa=F*ka/(ka+kg)=40 MN.","failure":"常見誤解：「只知道壩高就能決定拱向分力」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Dam height alone determines the arch load share.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「拱座相容與分力」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Abutment compatibility and load sharing”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b202-v15-01-k1","title":"拱座相容與分力","titleEn":"Abutment compatibility and load sharing","text":"拱重力壩把一部分水平荷載沿拱圈送到兩岸，也把一部分荷載透過壩底傳入基礎。教材以同位移的平行彈簧理解剛度與分力，不把它當成真實拱壩公式。","textEn":"An arch-gravity dam transfers some horizontal load toward the abutments and some through its base. Parallel springs with equal displacement illustrate stiffness-controlled sharing, not a real arch-dam design equation.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]},{"id":"b202-v15-01-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：只知道壩高就能決定拱向分力 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Dam height alone determines the arch load share. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]}],"quiz":{"question":"關於「拱座相容與分力」，下列哪一項敘述正確？","questionEn":"Which statement about \"Abutment compatibility and load sharing\" is correct?","options":["只知道壩高就能決定拱向分力","拱重力壩把一部分水平荷載沿拱圈送到兩岸，也把一部分荷載透過壩底傳入基礎。","只要量得裂縫長度就知道全部揚壓"],"optionsEn":["Dam height alone determines the arch load share.","An arch-gravity dam transfers some horizontal load toward the abutments and some through its base.","Crack length alone determines the complete uplift pressure distribution."],"answer":1,"explanation":"拱重力壩把一部分水平荷載沿拱圈送到兩岸，也把一部分荷載透過壩底傳入基礎。 其餘選項是常見誤解。","explanationEn":"An arch-gravity dam transfers some horizontal load toward the abutments and some through its base. The other options are common misconceptions."},"unit":1,"unitFacet":"mechanism","order":1,"sequence":13},{"id":"b202-v15-02","title":"拱座相容與分力：定量估算","titleEn":"Abutment compatibility and load sharing: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"],"prerequisiteIds":["b202-v15-01"],"objective":"以數值模型估算「拱座相容與分力」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Abutment compatibility and load sharing” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，輸入均非本工程操作參數：ka=8 GN/m; kg=12 GN/m; F=100 MN; Fa=F*ka/(ka+kg)=40 MN。模型邊界：線彈性且兩路徑同位移；未模擬三維拱殼、開裂或接觸滑移。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical example; inputs are not operating parameters of this project: ka=8 GN/m; kg=12 GN/m; F=100 MN; Fa=F*ka/(ka+kg)=40 MN. Model boundary: linear elasticity and equal displacement in both paths; excludes three-dimensional shell action, cracking and contact slip. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：在同一水位下比較壩體位移、拱座變形及溫度，避免用不同季節的位移直接反推剛度。","observationEn":"How to cross-check: Compare dam displacement, abutment deformation and temperature at the same reservoir level before inferring stiffness.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b202-v15-02-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，輸入均非本工程操作參數：ka=8 GN/m; kg=12 GN/m; F=100 MN; Fa=F*ka/(ka+kg)=40 MN。模型邊界：線彈性且兩路徑同位移；未模擬三維拱殼、開裂或接觸滑移。","textEn":"Original hypothetical example; inputs are not operating parameters of this project: ka=8 GN/m; kg=12 GN/m; F=100 MN; Fa=F*ka/(ka+kg)=40 MN. Model boundary: linear elasticity and equal displacement in both paths; excludes three-dimensional shell action, cracking and contact slip.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]},{"id":"b202-v15-02-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]}],"quiz":{"question":"依「拱座相容與分力」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Abutment compatibility and load sharing\", which statement holds?","options":["自由熱伸長就是受約束接縫閉合量","所有表面可採同一汽蝕數界線","原創假想算例，輸入均非本工程操作參數：ka=8 GN/m; kg=12 GN/m; F=100 MN; Fa=F*ka/(ka+kg)=40 MN。"],"optionsEn":["Free thermal extension equals closure of a restrained joint.","One cavitation-number threshold applies to every spillway surface.","Original hypothetical example; inputs are not operating parameters of this project: ka=8 GN/m; kg=12 GN/m; F=100 MN; Fa=F*ka/(ka+kg)=40 MN."],"answer":2,"explanation":"原創假想算例，輸入均非本工程操作參數：ka=8 GN/m; kg=12 GN/m; F=100 MN; Fa=F*ka/(ka+kg)=40 MN。 重算時請保留單位。","explanationEn":"Original hypothetical example; inputs are not operating parameters of this project: ka=8 GN/m; kg=12 GN/m; F=100 MN; Fa=F*ka/(ka+kg)=40 MN. Keep units when recalculating."},"unit":1,"unitFacet":"model","order":2,"sequence":14},{"id":"b202-v15-03","title":"拱座相容與分力：試驗與驗證","titleEn":"Abutment compatibility and load sharing: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"],"prerequisiteIds":["b202-v15-02"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「拱座相容與分力」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Abutment compatibility and load sharing” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"在同一水位下比較壩體位移、拱座變形及溫度，避免用不同季節的位移直接反推剛度。以改變一個路徑剛度的敏感度分析檢查分力總和是否保持外力，並用多點量測辨認左右岸反應不對稱。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Compare dam displacement, abutment deformation and temperature at the same reservoir level before inferring stiffness. Change one path stiffness and confirm that load shares still sum to the applied force. Use several observations to distinguish an asymmetric abutment response from a uniform translation. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：把拱座路徑剛度減半，重算兩種分力與共同位移，畫出每個路徑的自由體圖，列出需要岩體試驗才能確認的模型參數。","observationEn":"Site practice: Halve the abutment-path stiffness and recalculate both load shares and common displacement. Draw a free-body diagram for each path and identify the parameters that require rock-mass testing before interpretation.","failure":"注意干擾：拱座節理張開會使承載路徑變軟並把荷載移向其他部位；若只校準壩頂單點位移，可能得到看似正確的總剛度，卻完全錯判局部應力集中。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Opening abutment joints soften one load path and transfer force elsewhere. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b202-v15-03-k1","title":"驗證方法","titleEn":"Verification method","text":"在同一水位下比較壩體位移、拱座變形及溫度，避免用不同季節的位移直接反推剛度。以改變一個路徑剛度的敏感度分析檢查分力總和是否保持外力，並用多點量測辨認左右岸反應不對稱。","textEn":"Compare dam displacement, abutment deformation and temperature at the same reservoir level before inferring stiffness. Change one path stiffness and confirm that load shares still sum to the applied force. Use several observations to distinguish an asymmetric abutment response from a uniform translation.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]},{"id":"b202-v15-03-k2","title":"現場實務","titleEn":"Site practice","text":"把拱座路徑剛度減半，重算兩種分力與共同位移，畫出每個路徑的自由體圖，列出需要岩體試驗才能確認的模型參數。","textEn":"Halve the abutment-path stiffness and recalculate both load shares and common displacement. Draw a free-body diagram for each path and identify the parameters that require rock-mass testing before interpretation.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]}],"quiz":{"question":"要驗證「拱座相容與分力」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Abutment compatibility and load sharing\"?","options":["在同一水位下比較壩體位移、拱座變形及溫度，避免用不同季節的位移直接反推剛度。","量測時不必記錄溫度、水頭、水位歷程與施工荷重，因為它們不會影響結果。","岸線移動距離就是沉積前緣移動距離"],"optionsEn":["Compare dam displacement, abutment deformation and temperature at the same reservoir level before inferring stiffness.","Temperature, water head, water-level history and construction loads need not be recorded because they cannot affect the result.","Shoreline movement equals the movement of the sediment front."],"answer":0,"explanation":"在同一水位下比較壩體位移、拱座變形及溫度，避免用不同季節的位移直接反推剛度。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Compare dam displacement, abutment deformation and temperature at the same reservoir level before inferring stiffness. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":1,"unitFacet":"verification","order":3,"sequence":15},{"id":"b202-v15-04","title":"拱座相容與分力：失效診斷","titleEn":"Abutment compatibility and load sharing: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"],"prerequisiteIds":["b202-v15-03"],"objective":"從症狀倒推「拱座相容與分力」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Abutment compatibility and load sharing” and propose discriminating checks, corrective actions and prevention.","instruction":"拱座節理張開會使承載路徑變軟並把荷載移向其他部位；若只校準壩頂單點位移，可能得到看似正確的總剛度，卻完全錯判局部應力集中。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Opening abutment joints soften one load path and transfer force elsewhere. Calibrating only one crest displacement may reproduce overall stiffness while completely misrepresenting local stress concentrations and the distribution of support reactions. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：平行彈簧共同位移來自相容條件，若兩岸支承本身移動，需把支承位移加入，分力比例就不再只由剛度決定。","observationEn":"Link to the mechanism: Equal spring displacement follows compatibility; moving supports introduce imposed displacements, after which stiffness ratios alone no longer determine the force shares between the paths.","failure":"誤判風險：若相信「只知道壩高就能決定拱向分力」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Dam height alone determines the arch load share.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b202-v15-04-k1","title":"失效模式","titleEn":"Failure mode","text":"拱座節理張開會使承載路徑變軟並把荷載移向其他部位；若只校準壩頂單點位移，可能得到看似正確的總剛度，卻完全錯判局部應力集中。","textEn":"Opening abutment joints soften one load path and transfer force elsewhere. Calibrating only one crest displacement may reproduce overall stiffness while completely misrepresenting local stress concentrations and the distribution of support reactions.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]},{"id":"b202-v15-04-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]}],"quiz":{"question":"在「拱座相容與分力」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Abutment compatibility and load sharing\" shows distress, which diagnosis is most reasonable?","options":["所有異常都來自施工人員失誤，設計與細部不需要檢討。","拱座節理張開會使承載路徑變軟並把荷載移向其他部位；若只校準壩頂單點位移，可能得到看似正確的總剛度，卻完全錯判局部應力集中。","只要量得裂縫長度就知道全部揚壓"],"optionsEn":["Every anomaly is a workmanship error, so design and detailing never need review.","Opening abutment joints soften one load path and transfer force elsewhere.","Crack length alone determines the complete uplift pressure distribution."],"answer":1,"explanation":"拱座節理張開會使承載路徑變軟並把荷載移向其他部位；若只校準壩頂單點位移，可能得到看似正確的總剛度，卻完全錯判局部應力集中。 需以量測區分可能原因。","explanationEn":"Opening abutment joints soften one load path and transfer force elsewhere. Discriminate candidate causes by measurement."},"unit":1,"unitFacet":"failure","order":4,"sequence":16},{"id":"b202-v15-05","title":"裂縫連通與揚壓：機制與系統路徑","titleEn":"Crack connectivity and uplift: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"],"prerequisiteIds":["b202-v15-04"],"objective":"說明「裂縫連通與揚壓」如何影響胡佛壩的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Crack connectivity and uplift” governs forces, deformation, flow or signals in “Hoover Dam”, and map the relevant inputs, transfer paths and boundaries.","instruction":"基礎裂縫是否與上游水連通，會改變揚壓分布而不只是減少受壓面積。教材把已假設的壓力分布積分成向上合力，再討論裂縫開口與排水能力對分布的影響。裂縫長度不能獨立決定壓力，因流動阻力、下游水位與排水孔都參與控制。 排水點可能讓壓力圖出現折線，積分時應按各段面積相加，作用點也必須用各段力矩求得。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「裂縫連通與揚壓」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Whether a foundation crack connects to upstream water changes uplift distribution as well as contact area. Integrating an explicitly assumed pressure diagram gives the upward resultant; crack aperture and drainage then explain possible changes to that diagram. Crack length alone cannot determine pressure because flow resistance, tailwater and drains also control it. A drain may introduce a breakpoint in the pressure diagram; sum segment areas for force and segment moments for the resultant location on the base. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Crack connectivity and uplift” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，輸入均非本工程操作參數：pu=900 kPa; pd=100 kPa; B=60 m; w=1 m; U=(pu+pd)/2*B*w=30000 kN。","observationEn":"Order-of-magnitude cue: Original hypothetical example; inputs are not operating parameters of this project: pu=900 kPa; pd=100 kPa; B=60 m; w=1 m; U=(pu+pd)/2*B*w=30000 kN.","failure":"常見誤解：「只要量得裂縫長度就知道全部揚壓」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Crack length alone determines the complete uplift pressure distribution.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「裂縫連通與揚壓」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Crack connectivity and uplift”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b202-v15-05-k1","title":"裂縫連通與揚壓","titleEn":"Crack connectivity and uplift","text":"基礎裂縫是否與上游水連通，會改變揚壓分布而不只是減少受壓面積。教材把已假設的壓力分布積分成向上合力，再討論裂縫開口與排水能力對分布的影響。","textEn":"Whether a foundation crack connects to upstream water changes uplift distribution as well as contact area. Integrating an explicitly assumed pressure diagram gives the upward resultant; crack aperture and drainage then explain possible changes to that diagram.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]},{"id":"b202-v15-05-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：只要量得裂縫長度就知道全部揚壓 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Crack length alone determines the complete uplift pressure distribution. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]}],"quiz":{"question":"關於「裂縫連通與揚壓」，下列哪一項敘述正確？","questionEn":"Which statement about \"Crack connectivity and uplift\" is correct?","options":["只要量得裂縫長度就知道全部揚壓","平均降溫達標就表示沒有梯度風險","基礎裂縫是否與上游水連通，會改變揚壓分布而不只是減少受壓面積。"],"optionsEn":["Crack length alone determines the complete uplift pressure distribution.","Meeting an average cooling target proves there is no gradient risk.","Whether a foundation crack connects to upstream water changes uplift distribution as well as contact area."],"answer":2,"explanation":"基礎裂縫是否與上游水連通，會改變揚壓分布而不只是減少受壓面積。 其餘選項是常見誤解。","explanationEn":"Whether a foundation crack connects to upstream water changes uplift distribution as well as contact area. The other options are common misconceptions."},"unit":2,"unitFacet":"mechanism","order":5,"sequence":17},{"id":"b202-v15-06","title":"裂縫連通與揚壓：定量估算","titleEn":"Crack connectivity and uplift: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"],"prerequisiteIds":["b202-v15-05"],"objective":"以數值模型估算「裂縫連通與揚壓」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Crack connectivity and uplift” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，輸入均非本工程操作參數：pu=900 kPa; pd=100 kPa; B=60 m; w=1 m; U=(pu+pd)/2*B*w=30000 kN。模型邊界：沿基底壓力線性且以一米壩長計算；不代表裂縫內實際壓力分布。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical example; inputs are not operating parameters of this project: pu=900 kPa; pd=100 kPa; B=60 m; w=1 m; U=(pu+pd)/2*B*w=30000 kN. Model boundary: linear basal pressure over a one-metre dam strip; not the measured distribution within an actual crack. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：將各測壓孔換算至共同基準的壓力水頭，再檢查高低庫水位期間的反應與時間差。","observationEn":"How to cross-check: Convert piezometer readings to pressure heads on one datum and compare their response and lag at different reservoir levels.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b202-v15-06-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，輸入均非本工程操作參數：pu=900 kPa; pd=100 kPa; B=60 m; w=1 m; U=(pu+pd)/2*B*w=30000 kN。模型邊界：沿基底壓力線性且以一米壩長計算；不代表裂縫內實際壓力分布。","textEn":"Original hypothetical example; inputs are not operating parameters of this project: pu=900 kPa; pd=100 kPa; B=60 m; w=1 m; U=(pu+pd)/2*B*w=30000 kN. Model boundary: linear basal pressure over a one-metre dam strip; not the measured distribution within an actual crack.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]},{"id":"b202-v15-06-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]}],"quiz":{"question":"依「裂縫連通與揚壓」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Crack connectivity and uplift\", which statement holds?","options":["原創假想算例，輸入均非本工程操作參數：pu=900 kPa; pd=100 kPa; B=60 m; w=1 m; U=(pu+pd)/2*B*w=30000 kN。","首波壓升必定是所有暫態最大壓力","低水頭可藉無限增加流量完全補償"],"optionsEn":["Original hypothetical example; inputs are not operating parameters of this project: pu=900 kPa; pd=100 kPa; B=60 m; w=1 m; U=(pu+pd)/2*B*w=30000 kN.","The first pressure rise is always the maximum of the whole transient.","Any low head can be fully compensated by unlimited discharge."],"answer":0,"explanation":"原創假想算例，輸入均非本工程操作參數：pu=900 kPa; pd=100 kPa; B=60 m; w=1 m; U=(pu+pd)/2*B*w=30000 kN。 重算時請保留單位。","explanationEn":"Original hypothetical example; inputs are not operating parameters of this project: pu=900 kPa; pd=100 kPa; B=60 m; w=1 m; U=(pu+pd)/2*B*w=30000 kN. Keep units when recalculating."},"unit":2,"unitFacet":"model","order":6,"sequence":18},{"id":"b202-v15-07","title":"裂縫連通與揚壓：試驗與驗證","titleEn":"Crack connectivity and uplift: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"],"prerequisiteIds":["b202-v15-06"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「裂縫連通與揚壓」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Crack connectivity and uplift” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"將各測壓孔換算至共同基準的壓力水頭，再檢查高低庫水位期間的反應與時間差。以排水流量配對判讀：壓力上升但流量下降支持堵塞假說，壓力與流量同升則須追查新增連通路徑。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Convert piezometer readings to pressure heads on one datum and compare their response and lag at different reservoir levels. Pair pressure with drainage flow: rising pressure with falling flow supports blockage, while simultaneous increases require investigation of a newly connected seepage path. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：比較線性分布與上游半段保持高壓的分段分布，分別求合力及作用點，說明相同上游水位下為何抗滑與傾覆判斷都會改變。","observationEn":"Site practice: Compare the linear diagram with a piecewise diagram retaining high pressure over the upstream half. Find each resultant and its location, then explain changes in both sliding and overturning interpretation.","failure":"注意干擾：未辨認堵塞仍沿用原先低揚壓分布，會高估有效壩重與抗滑餘量；但測管氣泡或堵管也能產生假訊號，需以沖洗紀錄及鄰孔讀值交叉確認。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Using an old low-uplift diagram after drainage blockage overstates effective weight and sliding resistance. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b202-v15-07-k1","title":"驗證方法","titleEn":"Verification method","text":"將各測壓孔換算至共同基準的壓力水頭，再檢查高低庫水位期間的反應與時間差。以排水流量配對判讀：壓力上升但流量下降支持堵塞假說，壓力與流量同升則須追查新增連通路徑。","textEn":"Convert piezometer readings to pressure heads on one datum and compare their response and lag at different reservoir levels. Pair pressure with drainage flow: rising pressure with falling flow supports blockage, while simultaneous increases require investigation of a newly connected seepage path.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]},{"id":"b202-v15-07-k2","title":"現場實務","titleEn":"Site practice","text":"比較線性分布與上游半段保持高壓的分段分布，分別求合力及作用點，說明相同上游水位下為何抗滑與傾覆判斷都會改變。","textEn":"Compare the linear diagram with a piecewise diagram retaining high pressure over the upstream half. Find each resultant and its location, then explain changes in both sliding and overturning interpretation.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]}],"quiz":{"question":"要驗證「裂縫連通與揚壓」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Crack connectivity and uplift\"?","options":["沿用另一處水工設施或流域的量測結果，就可視為本工程已完成驗證。","將各測壓孔換算至共同基準的壓力水頭，再檢查高低庫水位期間的反應與時間差。","溫漂校正應消除所有壩體季節位移"],"optionsEn":["Reusing results from another hydraulic structure or catchment counts as verifying this structure.","Convert piezometer readings to pressure heads on one datum and compare their response and lag at different reservoir levels.","Thermal drift correction should remove all seasonal movement of the dam."],"answer":1,"explanation":"將各測壓孔換算至共同基準的壓力水頭，再檢查高低庫水位期間的反應與時間差。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Convert piezometer readings to pressure heads on one datum and compare their response and lag at different reservoir levels. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":2,"unitFacet":"verification","order":7,"sequence":19},{"id":"b202-v15-08","title":"裂縫連通與揚壓：失效診斷","titleEn":"Crack connectivity and uplift: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"],"prerequisiteIds":["b202-v15-07"],"objective":"從症狀倒推「裂縫連通與揚壓」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Crack connectivity and uplift” and propose discriminating checks, corrective actions and prevention.","instruction":"未辨認堵塞仍沿用原先低揚壓分布，會高估有效壩重與抗滑餘量；但測管氣泡或堵管也能產生假訊號，需以沖洗紀錄及鄰孔讀值交叉確認。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Using an old low-uplift diagram after drainage blockage overstates effective weight and sliding resistance. Air or blockage in the measuring tube can also create false signals, so maintenance records and neighboring readings must corroborate the interpretation. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：排水點可能讓壓力圖出現折線，積分時應按各段面積相加，作用點也必須用各段力矩求得。","observationEn":"Link to the mechanism: A drain may introduce a breakpoint in the pressure diagram; sum segment areas for force and segment moments for the resultant location on the base.","failure":"誤判風險：若相信「只要量得裂縫長度就知道全部揚壓」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Crack length alone determines the complete uplift pressure distribution.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b202-v15-08-k1","title":"失效模式","titleEn":"Failure mode","text":"未辨認堵塞仍沿用原先低揚壓分布，會高估有效壩重與抗滑餘量；但測管氣泡或堵管也能產生假訊號，需以沖洗紀錄及鄰孔讀值交叉確認。","textEn":"Using an old low-uplift diagram after drainage blockage overstates effective weight and sliding resistance. Air or blockage in the measuring tube can also create false signals, so maintenance records and neighboring readings must corroborate the interpretation.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]},{"id":"b202-v15-08-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]}],"quiz":{"question":"在「裂縫連通與揚壓」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Crack connectivity and uplift\" shows distress, which diagnosis is most reasonable?","options":["補一層塗料或放寬允收值，就能解決大多數劣化問題。","平均降溫達標就表示沒有梯度風險","未辨認堵塞仍沿用原先低揚壓分布，會高估有效壩重與抗滑餘量；但測管氣泡或堵管也能產生假訊號，需以沖洗紀錄及鄰孔讀值交叉確認。"],"optionsEn":["Adding a coat of paint or widening the acceptance limits solves most deterioration problems.","Meeting an average cooling target proves there is no gradient risk.","Using an old low-uplift diagram after drainage blockage overstates effective weight and sliding resistance."],"answer":2,"explanation":"未辨認堵塞仍沿用原先低揚壓分布，會高估有效壩重與抗滑餘量；但測管氣泡或堵管也能產生假訊號，需以沖洗紀錄及鄰孔讀值交叉確認。 需以量測區分可能原因。","explanationEn":"Using an old low-uplift diagram after drainage blockage overstates effective weight and sliding resistance. Discriminate candidate causes by measurement."},"unit":2,"unitFacet":"failure","order":8,"sequence":20}],"order":4},{"id":"b202-v15-s2","title":"水力機制、材料與定量模型","titleEn":"Hydraulics, materials and quantitative models","description":"本階段聚焦「混凝土冷卻熱量」與「接縫閉合與溫度」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Concrete cooling heat account\" and \"Joint closure and temperature\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b202-v15-09","title":"混凝土冷卻熱量：機制與系統路徑","titleEn":"Concrete cooling heat account: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"],"prerequisiteIds":["b202-v15-08"],"objective":"說明「混凝土冷卻熱量」如何影響胡佛壩的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Concrete cooling heat account” governs forces, deformation, flow or signals in “Hoover Dam”, and map the relevant inputs, transfer paths and boundaries.","instruction":"大體積混凝土降溫同時涉及熱量移除與空間溫差，兩者不可互相代替。比熱模型能估算均勻降溫所需移除的顯熱，但表面冷得過快可能提高內外約束應力。需把水化熱產生、冷卻水帶走熱量與周邊散熱分列，才能判斷熱量帳是否閉合。 熱擴散時間隨特徵長度平方變化，縮小試件的冷卻曲線不能直接按時間等比例搬到大體積壩塊。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「混凝土冷卻熱量」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Cooling mass concrete involves both heat removal and spatial gradients, which are not interchangeable. Heat capacity estimates sensible energy for uniform cooling, while rapid surface cooling can increase restraint stresses. Separate hydration heat, heat carried by cooling water and environmental exchange to establish whether the thermal account actually closes. Thermal diffusion time scales with characteristic length squared, so cooling observations from small specimens cannot be transferred to massive blocks by simple linear time scaling. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Concrete cooling heat account” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，輸入均非本工程操作參數：V=5000 m3; rho=2400 kg/m3; c=900 J/(kg*K); dT=8 K; E=V*rho*c*dT/1e9=86.4 GJ。","observationEn":"Order-of-magnitude cue: Original hypothetical example; inputs are not operating parameters of this project: V=5000 m3; rho=2400 kg/m3; c=900 J/(kg*K); dT=8 K; E=V*rho*c*dT/1e9=86.4 GJ.","failure":"常見誤解：「平均降溫達標就表示沒有梯度風險」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Meeting an average cooling target proves there is no gradient risk.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「混凝土冷卻熱量」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Concrete cooling heat account”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b202-v15-09-k1","title":"混凝土冷卻熱量","titleEn":"Concrete cooling heat account","text":"大體積混凝土降溫同時涉及熱量移除與空間溫差，兩者不可互相代替。比熱模型能估算均勻降溫所需移除的顯熱，但表面冷得過快可能提高內外約束應力。","textEn":"Cooling mass concrete involves both heat removal and spatial gradients, which are not interchangeable. Heat capacity estimates sensible energy for uniform cooling, while rapid surface cooling can increase restraint stresses.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]},{"id":"b202-v15-09-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：平均降溫達標就表示沒有梯度風險 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Meeting an average cooling target proves there is no gradient risk. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]}],"quiz":{"question":"關於「混凝土冷卻熱量」，下列哪一項敘述正確？","questionEn":"Which statement about \"Concrete cooling heat account\" is correct?","options":["大體積混凝土降溫同時涉及熱量移除與空間溫差，兩者不可互相代替。","平均降溫達標就表示沒有梯度風險","自由熱伸長就是受約束接縫閉合量"],"optionsEn":["Cooling mass concrete involves both heat removal and spatial gradients, which are not interchangeable.","Meeting an average cooling target proves there is no gradient risk.","Free thermal extension equals closure of a restrained joint."],"answer":0,"explanation":"大體積混凝土降溫同時涉及熱量移除與空間溫差，兩者不可互相代替。 其餘選項是常見誤解。","explanationEn":"Cooling mass concrete involves both heat removal and spatial gradients, which are not interchangeable. The other options are common misconceptions."},"unit":3,"unitFacet":"mechanism","order":1,"sequence":21},{"id":"b202-v15-10","title":"混凝土冷卻熱量：定量估算","titleEn":"Concrete cooling heat account: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"],"prerequisiteIds":["b202-v15-09"],"objective":"以數值模型估算「混凝土冷卻熱量」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Concrete cooling heat account” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，輸入均非本工程操作參數：V=5000 m3; rho=2400 kg/m3; c=900 J/(kg*K); dT=8 K; E=V*rho*c*dT/1e9=86.4 GJ。模型邊界：常數比熱與均勻溫降；未計持續水化熱及熱應力。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical example; inputs are not operating parameters of this project: V=5000 m3; rho=2400 kg/m3; c=900 J/(kg*K); dT=8 K; E=V*rho*c*dT/1e9=86.4 GJ. Model boundary: constant heat capacity and uniform cooling; continuing hydration heat and thermal stress are excluded. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：以核心、中間和表面溫度檢查均勻假設，再用冷卻水流量乘進出口溫差積分熱量。","observationEn":"How to cross-check: Check the uniform-temperature assumption using core, intermediate and surface readings, then integrate cooling-water flow times temperature rise.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b202-v15-10-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，輸入均非本工程操作參數：V=5000 m3; rho=2400 kg/m3; c=900 J/(kg*K); dT=8 K; E=V*rho*c*dT/1e9=86.4 GJ。模型邊界：常數比熱與均勻溫降；未計持續水化熱及熱應力。","textEn":"Original hypothetical example; inputs are not operating parameters of this project: V=5000 m3; rho=2400 kg/m3; c=900 J/(kg*K); dT=8 K; E=V*rho*c*dT/1e9=86.4 GJ. Model boundary: constant heat capacity and uniform cooling; continuing hydration heat and thermal stress are excluded.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]},{"id":"b202-v15-10-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]}],"quiz":{"question":"依「混凝土冷卻熱量」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Concrete cooling heat account\", which statement holds?","options":["所有表面可採同一汽蝕數界線","原創假想算例，輸入均非本工程操作參數：V=5000 m3; rho=2400 kg/m3; c=900 J/(kg*K); dT=8 K; E=V*rho*c*dT/1e9=86.4 GJ。","岸線移動距離就是沉積前緣移動距離"],"optionsEn":["One cavitation-number threshold applies to every spillway surface.","Original hypothetical example; inputs are not operating parameters of this project: V=5000 m3; rho=2400 kg/m3; c=900 J/(kg*K); dT=8 K; E=V*rho*c*dT/1e9=86.4 GJ.","Shoreline movement equals the movement of the sediment front."],"answer":1,"explanation":"原創假想算例，輸入均非本工程操作參數：V=5000 m3; rho=2400 kg/m3; c=900 J/(kg*K); dT=8 K; E=V*rho*c*dT/1e9=86.4 GJ。 重算時請保留單位。","explanationEn":"Original hypothetical example; inputs are not operating parameters of this project: V=5000 m3; rho=2400 kg/m3; c=900 J/(kg*K); dT=8 K; E=V*rho*c*dT/1e9=86.4 GJ. Keep units when recalculating."},"unit":3,"unitFacet":"model","order":2,"sequence":22},{"id":"b202-v15-11","title":"混凝土冷卻熱量：試驗與驗證","titleEn":"Concrete cooling heat account: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"],"prerequisiteIds":["b202-v15-10"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「混凝土冷卻熱量」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Concrete cooling heat account” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"以核心、中間和表面溫度檢查均勻假設，再用冷卻水流量乘進出口溫差積分熱量。若水側移熱量大於混凝土顯熱減少，應查水化熱與邊界交換，不可立即認定溫度儀表故障。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Check the uniform-temperature assumption using core, intermediate and surface readings, then integrate cooling-water flow times temperature rise. If water-side heat removal exceeds the concrete sensible-energy decrease, investigate hydration and boundary exchange before assuming the temperature instruments are defective. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：對同一熱量設計均勻與偏側冷卻兩個假想溫度剖面，指出哪些測點能區分兩者，再估算多移除一開爾文顯熱所需的額外能量。","observationEn":"Site practice: Construct uniform and one-sided cooling profiles with the same total heat removal. Identify sensors that distinguish them, then calculate the additional sensible energy associated with one more kelvin of cooling.","failure":"注意干擾：冷卻太集中會造成局部溫度梯度及裂縫，即使平均溫度下降符合目標也可能出現問題；裂縫又改變水密與局部傳熱，因此不能只以總移熱量驗收冷卻品質。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Concentrated cooling can create local gradients and cracking even when average temperature meets its target. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b202-v15-11-k1","title":"驗證方法","titleEn":"Verification method","text":"以核心、中間和表面溫度檢查均勻假設，再用冷卻水流量乘進出口溫差積分熱量。若水側移熱量大於混凝土顯熱減少，應查水化熱與邊界交換，不可立即認定溫度儀表故障。","textEn":"Check the uniform-temperature assumption using core, intermediate and surface readings, then integrate cooling-water flow times temperature rise. If water-side heat removal exceeds the concrete sensible-energy decrease, investigate hydration and boundary exchange before assuming the temperature instruments are defective.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]},{"id":"b202-v15-11-k2","title":"現場實務","titleEn":"Site practice","text":"對同一熱量設計均勻與偏側冷卻兩個假想溫度剖面，指出哪些測點能區分兩者，再估算多移除一開爾文顯熱所需的額外能量。","textEn":"Construct uniform and one-sided cooling profiles with the same total heat removal. Identify sensors that distinguish them, then calculate the additional sensible energy associated with one more kelvin of cooling.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]}],"quiz":{"question":"要驗證「混凝土冷卻熱量」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Concrete cooling heat account\"?","options":["只看一次讀值或外觀即可判定合格，不需要基準點、參考試體或重複量測。","每增加一台備用設備就多一個獨立備援","以核心、中間和表面溫度檢查均勻假設，再用冷卻水流量乘進出口溫差積分熱量。"],"optionsEn":["A single reading or a visual impression is enough to accept the work; no datum, reference specimen or repeat measurement is needed.","Every additional spare device provides another fully independent backup.","Check the uniform-temperature assumption using core, intermediate and surface readings, then integrate cooling-water flow times temperature rise."],"answer":2,"explanation":"以核心、中間和表面溫度檢查均勻假設，再用冷卻水流量乘進出口溫差積分熱量。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Check the uniform-temperature assumption using core, intermediate and surface readings, then integrate cooling-water flow times temperature rise. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":3,"unitFacet":"verification","order":3,"sequence":23},{"id":"b202-v15-12","title":"混凝土冷卻熱量：失效診斷","titleEn":"Concrete cooling heat account: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"],"prerequisiteIds":["b202-v15-11"],"objective":"從症狀倒推「混凝土冷卻熱量」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Concrete cooling heat account” and propose discriminating checks, corrective actions and prevention.","instruction":"冷卻太集中會造成局部溫度梯度及裂縫，即使平均溫度下降符合目標也可能出現問題；裂縫又改變水密與局部傳熱，因此不能只以總移熱量驗收冷卻品質。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Concentrated cooling can create local gradients and cracking even when average temperature meets its target. Cracks subsequently alter watertightness and heat transfer, so total extracted energy alone cannot establish the quality of the cooling process. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：熱擴散時間隨特徵長度平方變化，縮小試件的冷卻曲線不能直接按時間等比例搬到大體積壩塊。","observationEn":"Link to the mechanism: Thermal diffusion time scales with characteristic length squared, so cooling observations from small specimens cannot be transferred to massive blocks by simple linear time scaling.","failure":"誤判風險：若相信「平均降溫達標就表示沒有梯度風險」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Meeting an average cooling target proves there is no gradient risk.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b202-v15-12-k1","title":"失效模式","titleEn":"Failure mode","text":"冷卻太集中會造成局部溫度梯度及裂縫，即使平均溫度下降符合目標也可能出現問題；裂縫又改變水密與局部傳熱，因此不能只以總移熱量驗收冷卻品質。","textEn":"Concentrated cooling can create local gradients and cracking even when average temperature meets its target. Cracks subsequently alter watertightness and heat transfer, so total extracted energy alone cannot establish the quality of the cooling process.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]},{"id":"b202-v15-12-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]}],"quiz":{"question":"在「混凝土冷卻熱量」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Concrete cooling heat account\" shows distress, which diagnosis is most reasonable?","options":["冷卻太集中會造成局部溫度梯度及裂縫，即使平均溫度下降符合目標也可能出現問題；裂縫又改變水密與局部傳熱，因此不能只以總移熱量驗收冷卻品質。","裂縫或異常只出現一次就可以忽略，不需要記錄或追蹤。","自由熱伸長就是受約束接縫閉合量"],"optionsEn":["Concentrated cooling can create local gradients and cracking even when average temperature meets its target.","A crack or anomaly that appears only once can be ignored without logging or follow-up.","Free thermal extension equals closure of a restrained joint."],"answer":0,"explanation":"冷卻太集中會造成局部溫度梯度及裂縫，即使平均溫度下降符合目標也可能出現問題；裂縫又改變水密與局部傳熱，因此不能只以總移熱量驗收冷卻品質。 需以量測區分可能原因。","explanationEn":"Concentrated cooling can create local gradients and cracking even when average temperature meets its target. Discriminate candidate causes by measurement."},"unit":3,"unitFacet":"failure","order":4,"sequence":24},{"id":"b202-v15-13","title":"接縫閉合與溫度：機制與系統路徑","titleEn":"Joint closure and temperature: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"],"prerequisiteIds":["b202-v15-12"],"objective":"說明「接縫閉合與溫度」如何影響胡佛壩的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Joint closure and temperature” governs forces, deformation, flow or signals in “Hoover Dam”, and map the relevant inputs, transfer paths and boundaries.","instruction":"分塊澆置留下的接縫，其開合取決於塊體自由熱變形、相鄰約束與水壓。線膨脹模型只描述未受約束的長度變化，接縫灌漿後的應力則需用實際約束分析。不能把某溫度下的縫寬直接解讀為永久缺陷，也不能把所有縫寬變化都歸於氣溫。 接縫量測方向若與縫面法線不一致，需將位移投影分解，否則剪切位移也可能混入開合讀值。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「接縫閉合與溫度」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"A joint between concrete blocks opens or closes through thermal strain, neighboring restraint and water loading. Linear expansion describes free length change only; stress after grouting depends on actual restraint. Joint width at one temperature is not automatically a permanent defect, and not every width change can be attributed to air temperature. A gauge not aligned with the joint normal requires displacement projection; otherwise tangential movement can contaminate the apparent opening or closure of the joint. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Joint closure and temperature” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，輸入均非本工程操作參數：alpha=0.00001 1/K; L=18 m; dT=12 K; dL=alpha*L*dT*1000=2.16 mm。","observationEn":"Order-of-magnitude cue: Original hypothetical example; inputs are not operating parameters of this project: alpha=0.00001 1/K; L=18 m; dT=12 K; dL=alpha*L*dT*1000=2.16 mm.","failure":"常見誤解：「自由熱伸長就是受約束接縫閉合量」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Free thermal extension equals closure of a restrained joint.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「接縫閉合與溫度」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Joint closure and temperature”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b202-v15-13-k1","title":"接縫閉合與溫度","titleEn":"Joint closure and temperature","text":"分塊澆置留下的接縫，其開合取決於塊體自由熱變形、相鄰約束與水壓。線膨脹模型只描述未受約束的長度變化，接縫灌漿後的應力則需用實際約束分析。","textEn":"A joint between concrete blocks opens or closes through thermal strain, neighboring restraint and water loading. Linear expansion describes free length change only; stress after grouting depends on actual restraint.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]},{"id":"b202-v15-13-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：自由熱伸長就是受約束接縫閉合量 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Free thermal extension equals closure of a restrained joint. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]}],"quiz":{"question":"關於「接縫閉合與溫度」，下列哪一項敘述正確？","questionEn":"Which statement about \"Joint closure and temperature\" is correct?","options":["自由熱伸長就是受約束接縫閉合量","分塊澆置留下的接縫，其開合取決於塊體自由熱變形、相鄰約束與水壓。","首波壓升必定是所有暫態最大壓力"],"optionsEn":["Free thermal extension equals closure of a restrained joint.","A joint between concrete blocks opens or closes through thermal strain, neighboring restraint and water loading.","The first pressure rise is always the maximum of the whole transient."],"answer":1,"explanation":"分塊澆置留下的接縫，其開合取決於塊體自由熱變形、相鄰約束與水壓。 其餘選項是常見誤解。","explanationEn":"A joint between concrete blocks opens or closes through thermal strain, neighboring restraint and water loading. The other options are common misconceptions."},"unit":4,"unitFacet":"mechanism","order":5,"sequence":25},{"id":"b202-v15-14","title":"接縫閉合與溫度：定量估算","titleEn":"Joint closure and temperature: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"],"prerequisiteIds":["b202-v15-13"],"objective":"以數值模型估算「接縫閉合與溫度」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Joint closure and temperature” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，輸入均非本工程操作參數：alpha=0.00001 1/K; L=18 m; dT=12 K; dL=alpha*L*dT*1000=2.16 mm。模型邊界：單一塊體沿量測方向自由膨脹；不是受約束接縫的實際閉合量。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical example; inputs are not operating parameters of this project: alpha=0.00001 1/K; L=18 m; dT=12 K; dL=alpha*L*dT*1000=2.16 mm. Model boundary: free expansion of one block along the measurement axis; not the actual closure of a restrained joint. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：將接縫計讀值與塊體內部溫度及庫水位同步繪圖，查看升溫與降溫路徑是否重合。","observationEn":"How to cross-check: Plot joint readings with internal block temperature and reservoir level, checking whether warming and cooling paths coincide.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b202-v15-14-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，輸入均非本工程操作參數：alpha=0.00001 1/K; L=18 m; dT=12 K; dL=alpha*L*dT*1000=2.16 mm。模型邊界：單一塊體沿量測方向自由膨脹；不是受約束接縫的實際閉合量。","textEn":"Original hypothetical example; inputs are not operating parameters of this project: alpha=0.00001 1/K; L=18 m; dT=12 K; dL=alpha*L*dT*1000=2.16 mm. Model boundary: free expansion of one block along the measurement axis; not the actual closure of a restrained joint.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]},{"id":"b202-v15-14-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]}],"quiz":{"question":"依「接縫閉合與溫度」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Joint closure and temperature\", which statement holds?","options":["低水頭可藉無限增加流量完全補償","溫漂校正應消除所有壩體季節位移","原創假想算例，輸入均非本工程操作參數：alpha=0.00001 1/K; L=18 m; dT=12 K; dL=alpha*L*dT*1000=2.16 mm。"],"optionsEn":["Any low head can be fully compensated by unlimited discharge.","Thermal drift correction should remove all seasonal movement of the dam.","Original hypothetical example; inputs are not operating parameters of this project: alpha=0.00001 1/K; L=18 m; dT=12 K; dL=alpha*L*dT*1000=2.16 mm."],"answer":2,"explanation":"原創假想算例，輸入均非本工程操作參數：alpha=0.00001 1/K; L=18 m; dT=12 K; dL=alpha*L*dT*1000=2.16 mm。 重算時請保留單位。","explanationEn":"Original hypothetical example; inputs are not operating parameters of this project: alpha=0.00001 1/K; L=18 m; dT=12 K; dL=alpha*L*dT*1000=2.16 mm. Keep units when recalculating."},"unit":4,"unitFacet":"model","order":6,"sequence":26},{"id":"b202-v15-15","title":"接縫閉合與溫度：試驗與驗證","titleEn":"Joint closure and temperature: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"],"prerequisiteIds":["b202-v15-14"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「接縫閉合與溫度」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Joint closure and temperature” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"將接縫計讀值與塊體內部溫度及庫水位同步繪圖，查看升溫與降溫路徑是否重合。若有遲滯，再查接觸摩擦與裂縫連通；量測基座本身的熱伸縮也必須先校正，避免誤判壩體變形。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Plot joint readings with internal block temperature and reservoir level, checking whether warming and cooling paths coincide. Hysteresis calls for investigating contact friction or crack connectivity. Correct thermal movement of the instrument mounting itself before assigning the observed change to the dam. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：用三種熱膨脹係數重算自由伸長，另畫受約束與無約束兩個自由體圖，列出從位移轉成應力還缺少的剛度及接觸條件。","observationEn":"Site practice: Recalculate free extension for three thermal expansion coefficients. Draw restrained and unrestrained free-body diagrams, then list stiffness and contact information still needed to convert displacement into a stress estimate.","failure":"注意干擾：灌漿溫度與後續運轉溫度不相容時，可能造成過高接觸壓力或縫面重新張開；但單支接縫計也可能因固定端鬆動而跳值，需以附近位移證據區分。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: An incompatible grouting and service-temperature range can produce excessive contact pressure or reopening. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b202-v15-15-k1","title":"驗證方法","titleEn":"Verification method","text":"將接縫計讀值與塊體內部溫度及庫水位同步繪圖，查看升溫與降溫路徑是否重合。若有遲滯，再查接觸摩擦與裂縫連通；量測基座本身的熱伸縮也必須先校正，避免誤判壩體變形。","textEn":"Plot joint readings with internal block temperature and reservoir level, checking whether warming and cooling paths coincide. Hysteresis calls for investigating contact friction or crack connectivity. Correct thermal movement of the instrument mounting itself before assigning the observed change to the dam.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]},{"id":"b202-v15-15-k2","title":"現場實務","titleEn":"Site practice","text":"用三種熱膨脹係數重算自由伸長，另畫受約束與無約束兩個自由體圖，列出從位移轉成應力還缺少的剛度及接觸條件。","textEn":"Recalculate free extension for three thermal expansion coefficients. Draw restrained and unrestrained free-body diagrams, then list stiffness and contact information still needed to convert displacement into a stress estimate.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]}],"quiz":{"question":"要驗證「接縫閉合與溫度」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Joint closure and temperature\"?","options":["將接縫計讀值與塊體內部溫度及庫水位同步繪圖，查看升溫與降溫路徑是否重合。","不確定度太難估計，報告中只寫最佳值即可。","只知道壩高就能決定拱向分力"],"optionsEn":["Plot joint readings with internal block temperature and reservoir level, checking whether warming and cooling paths coincide.","Uncertainty is too hard to estimate, so the report may state only the best value.","Dam height alone determines the arch load share."],"answer":0,"explanation":"將接縫計讀值與塊體內部溫度及庫水位同步繪圖，查看升溫與降溫路徑是否重合。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Plot joint readings with internal block temperature and reservoir level, checking whether warming and cooling paths coincide. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":4,"unitFacet":"verification","order":7,"sequence":27},{"id":"b202-v15-16","title":"接縫閉合與溫度：失效診斷","titleEn":"Joint closure and temperature: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"],"prerequisiteIds":["b202-v15-15"],"objective":"從症狀倒推「接縫閉合與溫度」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Joint closure and temperature” and propose discriminating checks, corrective actions and prevention.","instruction":"灌漿溫度與後續運轉溫度不相容時，可能造成過高接觸壓力或縫面重新張開；但單支接縫計也可能因固定端鬆動而跳值，需以附近位移證據區分。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"An incompatible grouting and service-temperature range can produce excessive contact pressure or reopening. A loose gauge anchor can also cause a sudden reading change, requiring neighboring displacement evidence to distinguish the instrument fault from physical joint behavior. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：接縫量測方向若與縫面法線不一致，需將位移投影分解，否則剪切位移也可能混入開合讀值。","observationEn":"Link to the mechanism: A gauge not aligned with the joint normal requires displacement projection; otherwise tangential movement can contaminate the apparent opening or closure of the joint.","failure":"誤判風險：若相信「自由熱伸長就是受約束接縫閉合量」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Free thermal extension equals closure of a restrained joint.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b202-v15-16-k1","title":"失效模式","titleEn":"Failure mode","text":"灌漿溫度與後續運轉溫度不相容時，可能造成過高接觸壓力或縫面重新張開；但單支接縫計也可能因固定端鬆動而跳值，需以附近位移證據區分。","textEn":"An incompatible grouting and service-temperature range can produce excessive contact pressure or reopening. A loose gauge anchor can also cause a sudden reading change, requiring neighboring displacement evidence to distinguish the instrument fault from physical joint behavior.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]},{"id":"b202-v15-16-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]}],"quiz":{"question":"在「接縫閉合與溫度」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Joint closure and temperature\" shows distress, which diagnosis is most reasonable?","options":["先更換最貴的構件；只要症狀消失，就代表已找到根因。","灌漿溫度與後續運轉溫度不相容時，可能造成過高接觸壓力或縫面重新張開；但單支接縫計也可能因固定端鬆動而跳值，需以附近位移證據區分。","首波壓升必定是所有暫態最大壓力"],"optionsEn":["Replace the most expensive component first; if the symptom disappears, the root cause has been found.","An incompatible grouting and service-temperature range can produce excessive contact pressure or reopening.","The first pressure rise is always the maximum of the whole transient."],"answer":1,"explanation":"灌漿溫度與後續運轉溫度不相容時，可能造成過高接觸壓力或縫面重新張開；但單支接縫計也可能因固定端鬆動而跳值，需以附近位移證據區分。 需以量測區分可能原因。","explanationEn":"An incompatible grouting and service-temperature range can produce excessive contact pressure or reopening. Discriminate candidate causes by measurement."},"unit":4,"unitFacet":"failure","order":8,"sequence":28}],"order":5},{"id":"b202-v15-s3","title":"施工方法與施工階段控制","titleEn":"Construction methods and stage control","description":"本階段聚焦「壓力鋼管水錘」與「溢洪面汽蝕指標」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Penstock water hammer\" and \"Spillway cavitation indicator\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b202-v15-17","title":"壓力鋼管水錘：機制與系統路徑","titleEn":"Penstock water hammer: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"],"prerequisiteIds":["b202-v15-16"],"objective":"說明「壓力鋼管水錘」如何影響胡佛壩的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Penstock water hammer” governs forces, deformation, flow or signals in “Hoover Dam”, and map the relevant inputs, transfer paths and boundaries.","instruction":"導葉或閥門快速變動使水流動量轉為壓力波，波速同時受水的可壓縮性與管壁彈性影響。焦科夫斯基關係適合估計快速速度改變的首波幅度；反射、分岔與調壓設施會改變後續波形，因此單一首波不能取代整段管路的暫態包絡。 反射的符號取決於邊界阻抗，水庫端與封閉閥端可能產生不同反射，因此應在時空圖標明每個邊界。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「壓力鋼管水錘」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Rapid guide-vane or valve movement converts flow momentum into a pressure wave whose speed depends on water compressibility and pipe elasticity. The Joukowsky relation estimates the first wave from a rapid velocity change. Reflections, branches and surge facilities alter later waves, so one first-wave estimate is not a full transient envelope. Reflection sign depends on boundary impedance; reservoir and closed-valve ends can reflect differently, so every boundary must be identified on the space-time diagram. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Penstock water hammer” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，輸入均非本工程操作參數：rho=1000 kg/m3; a=900 m/s; dv=0.7 m/s; dp=rho*a*dv/1e6=0.63 MPa。","observationEn":"Order-of-magnitude cue: Original hypothetical example; inputs are not operating parameters of this project: rho=1000 kg/m3; a=900 m/s; dv=0.7 m/s; dp=rho*a*dv/1e6=0.63 MPa.","failure":"常見誤解：「首波壓升必定是所有暫態最大壓力」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"The first pressure rise is always the maximum of the whole transient.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「壓力鋼管水錘」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Penstock water hammer”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b202-v15-17-k1","title":"壓力鋼管水錘","titleEn":"Penstock water hammer","text":"導葉或閥門快速變動使水流動量轉為壓力波，波速同時受水的可壓縮性與管壁彈性影響。焦科夫斯基關係適合估計快速速度改變的首波幅度；反射、分岔與調壓設施會改變後續波形，因此單一首波不能取代整段管路的暫態包絡。","textEn":"Rapid guide-vane or valve movement converts flow momentum into a pressure wave whose speed depends on water compressibility and pipe elasticity. The Joukowsky relation estimates the first wave from a rapid velocity change.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]},{"id":"b202-v15-17-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：首波壓升必定是所有暫態最大壓力 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: The first pressure rise is always the maximum of the whole transient. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]}],"quiz":{"question":"關於「壓力鋼管水錘」，下列哪一項敘述正確？","questionEn":"Which statement about \"Penstock water hammer\" is correct?","options":["首波壓升必定是所有暫態最大壓力","所有表面可採同一汽蝕數界線","導葉或閥門快速變動使水流動量轉為壓力波，波速同時受水的可壓縮性與管壁彈性影響。"],"optionsEn":["The first pressure rise is always the maximum of the whole transient.","One cavitation-number threshold applies to every spillway surface.","Rapid guide-vane or valve movement converts flow momentum into a pressure wave whose speed depends on water compressibility and pipe elasticity."],"answer":2,"explanation":"導葉或閥門快速變動使水流動量轉為壓力波，波速同時受水的可壓縮性與管壁彈性影響。 其餘選項是常見誤解。","explanationEn":"Rapid guide-vane or valve movement converts flow momentum into a pressure wave whose speed depends on water compressibility and pipe elasticity. The other options are common misconceptions."},"unit":5,"unitFacet":"mechanism","order":1,"sequence":29},{"id":"b202-v15-18","title":"壓力鋼管水錘：定量估算","titleEn":"Penstock water hammer: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"],"prerequisiteIds":["b202-v15-17"],"objective":"以數值模型估算「壓力鋼管水錘」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Penstock water hammer” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，輸入均非本工程操作參數：rho=1000 kg/m3; a=900 m/s; dv=0.7 m/s; dp=rho*a*dv/1e6=0.63 MPa。模型邊界：速度變化快於相關往返波時間，單相彈性首波；未含汽穴與反射疊加。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical example; inputs are not operating parameters of this project: rho=1000 kg/m3; a=900 m/s; dv=0.7 m/s; dp=rho*a*dv/1e6=0.63 MPa. Model boundary: velocity change is faster than the relevant wave round-trip time; single-phase elastic first wave without cavitation or reflected-wave superposition. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：先以管長與波速估算往返時間，再比較控制動作時間及高速壓力記錄。","observationEn":"How to cross-check: Estimate round-trip time from pipe length and wave speed, then compare actuator timing with rapid pressure records.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b202-v15-18-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，輸入均非本工程操作參數：rho=1000 kg/m3; a=900 m/s; dv=0.7 m/s; dp=rho*a*dv/1e6=0.63 MPa。模型邊界：速度變化快於相關往返波時間，單相彈性首波；未含汽穴與反射疊加。","textEn":"Original hypothetical example; inputs are not operating parameters of this project: rho=1000 kg/m3; a=900 m/s; dv=0.7 m/s; dp=rho*a*dv/1e6=0.63 MPa. Model boundary: velocity change is faster than the relevant wave round-trip time; single-phase elastic first wave without cavitation or reflected-wave superposition.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]},{"id":"b202-v15-18-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]}],"quiz":{"question":"依「壓力鋼管水錘」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Penstock water hammer\", which statement holds?","options":["原創假想算例，輸入均非本工程操作參數：rho=1000 kg/m3; a=900 m/s; dv=0.7 m/s; dp=rho*a*dv/1e6=0.63 MPa。","岸線移動距離就是沉積前緣移動距離","每增加一台備用設備就多一個獨立備援"],"optionsEn":["Original hypothetical example; inputs are not operating parameters of this project: rho=1000 kg/m3; a=900 m/s; dv=0.7 m/s; dp=rho*a*dv/1e6=0.63 MPa.","Shoreline movement equals the movement of the sediment front.","Every additional spare device provides another fully independent backup."],"answer":0,"explanation":"原創假想算例，輸入均非本工程操作參數：rho=1000 kg/m3; a=900 m/s; dv=0.7 m/s; dp=rho*a*dv/1e6=0.63 MPa。 重算時請保留單位。","explanationEn":"Original hypothetical example; inputs are not operating parameters of this project: rho=1000 kg/m3; a=900 m/s; dv=0.7 m/s; dp=rho*a*dv/1e6=0.63 MPa. Keep units when recalculating."},"unit":5,"unitFacet":"model","order":2,"sequence":30},{"id":"b202-v15-19","title":"壓力鋼管水錘：試驗與驗證","titleEn":"Penstock water hammer: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"],"prerequisiteIds":["b202-v15-18"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「壓力鋼管水錘」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Penstock water hammer” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"先以管長與波速估算往返時間，再比較控制動作時間及高速壓力記錄。用兩測點峰值到達差檢查波速，若訊號含低壓平台或不連續回升，應追查汽穴及氣體效應，而非只修改阻力係數。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Estimate round-trip time from pipe length and wave speed, then compare actuator timing with rapid pressure records. Arrival differences between two sensors test wave speed. Low-pressure plateaus or abrupt recovery warrant investigation of cavitation and gas effects rather than merely changing friction coefficients. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：分別把速度變化減半及波速降低，計算首波幅度，再用示意時空圖標出反射路徑，寫明何時必須改用完整特徵線暫態模型。","observationEn":"Site practice: Halve the velocity change and reduce wave speed in separate cases. Calculate first-wave amplitudes, mark reflection paths on a space-time diagram, and state when a full method-of-characteristics transient model is required.","failure":"注意干擾：延遲關閉或不協調的保護動作可能形成多次反射峰值，最大壓力不一定在首波；低壓端的液柱分離也可能在重新接合時產生更大衝擊。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Delayed or uncoordinated protective actions can produce repeated reflected peaks, with the maximum occurring after the first wave. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b202-v15-19-k1","title":"驗證方法","titleEn":"Verification method","text":"先以管長與波速估算往返時間，再比較控制動作時間及高速壓力記錄。用兩測點峰值到達差檢查波速，若訊號含低壓平台或不連續回升，應追查汽穴及氣體效應，而非只修改阻力係數。","textEn":"Estimate round-trip time from pipe length and wave speed, then compare actuator timing with rapid pressure records. Arrival differences between two sensors test wave speed. Low-pressure plateaus or abrupt recovery warrant investigation of cavitation and gas effects rather than merely changing friction coefficients.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]},{"id":"b202-v15-19-k2","title":"現場實務","titleEn":"Site practice","text":"分別把速度變化減半及波速降低，計算首波幅度，再用示意時空圖標出反射路徑，寫明何時必須改用完整特徵線暫態模型。","textEn":"Halve the velocity change and reduce wave speed in separate cases. Calculate first-wave amplitudes, mark reflection paths on a space-time diagram, and state when a full method-of-characteristics transient model is required.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]}],"quiz":{"question":"要驗證「壓力鋼管水錘」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Penstock water hammer\"?","options":["允收準則可以等看到量測數據後再決定。","先以管長與波速估算往返時間，再比較控制動作時間及高速壓力記錄。","只要量得裂縫長度就知道全部揚壓"],"optionsEn":["Acceptance criteria can be decided after the measured data have been seen.","Estimate round-trip time from pipe length and wave speed, then compare actuator timing with rapid pressure records.","Crack length alone determines the complete uplift pressure distribution."],"answer":1,"explanation":"先以管長與波速估算往返時間，再比較控制動作時間及高速壓力記錄。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Estimate round-trip time from pipe length and wave speed, then compare actuator timing with rapid pressure records. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":5,"unitFacet":"verification","order":3,"sequence":31},{"id":"b202-v15-20","title":"壓力鋼管水錘：失效診斷","titleEn":"Penstock water hammer: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"],"prerequisiteIds":["b202-v15-19"],"objective":"從症狀倒推「壓力鋼管水錘」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Penstock water hammer” and propose discriminating checks, corrective actions and prevention.","instruction":"延遲關閉或不協調的保護動作可能形成多次反射峰值，最大壓力不一定在首波；低壓端的液柱分離也可能在重新接合時產生更大衝擊。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Delayed or uncoordinated protective actions can produce repeated reflected peaks, with the maximum occurring after the first wave. Column separation on the low-pressure side can generate a larger impact when the separated liquid columns rejoin. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：反射的符號取決於邊界阻抗，水庫端與封閉閥端可能產生不同反射，因此應在時空圖標明每個邊界。","observationEn":"Link to the mechanism: Reflection sign depends on boundary impedance; reservoir and closed-valve ends can reflect differently, so every boundary must be identified on the space-time diagram.","failure":"誤判風險：若相信「首波壓升必定是所有暫態最大壓力」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"The first pressure rise is always the maximum of the whole transient.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b202-v15-20-k1","title":"失效模式","titleEn":"Failure mode","text":"延遲關閉或不協調的保護動作可能形成多次反射峰值，最大壓力不一定在首波；低壓端的液柱分離也可能在重新接合時產生更大衝擊。","textEn":"Delayed or uncoordinated protective actions can produce repeated reflected peaks, with the maximum occurring after the first wave. Column separation on the low-pressure side can generate a larger impact when the separated liquid columns rejoin.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]},{"id":"b202-v15-20-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]}],"quiz":{"question":"在「壓力鋼管水錘」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Penstock water hammer\" shows distress, which diagnosis is most reasonable?","options":["症狀相同就代表原因相同，不必用量測區分。","所有表面可採同一汽蝕數界線","延遲關閉或不協調的保護動作可能形成多次反射峰值，最大壓力不一定在首波；低壓端的液柱分離也可能在重新接合時產生更大衝擊。"],"optionsEn":["Identical symptoms always mean identical causes, so no discriminating measurement is needed.","One cavitation-number threshold applies to every spillway surface.","Delayed or uncoordinated protective actions can produce repeated reflected peaks, with the maximum occurring after the first wave."],"answer":2,"explanation":"延遲關閉或不協調的保護動作可能形成多次反射峰值，最大壓力不一定在首波；低壓端的液柱分離也可能在重新接合時產生更大衝擊。 需以量測區分可能原因。","explanationEn":"Delayed or uncoordinated protective actions can produce repeated reflected peaks, with the maximum occurring after the first wave. Discriminate candidate causes by measurement."},"unit":5,"unitFacet":"failure","order":4,"sequence":32},{"id":"b202-v15-21","title":"溢洪面汽蝕指標：機制與系統路徑","titleEn":"Spillway cavitation indicator: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"],"prerequisiteIds":["b202-v15-20"],"objective":"說明「溢洪面汽蝕指標」如何影響胡佛壩的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Spillway cavitation indicator” governs forces, deformation, flow or signals in “Hoover Dam”, and map the relevant inputs, transfer paths and boundaries.","instruction":"高速溢洪流在不平整表面附近會產生局部低壓，是否形成汽穴要比較局部絕對壓力與水的蒸氣壓。汽蝕數把可用壓力差除以動壓，便於比較流況，但臨界值仍依表面幾何、含氣與尺度而異。以平均壓力計算只能作初步篩查。 蒸氣壓取決於水溫，而局部絕對壓也受大氣壓影響，兩者均應使用與事件同時的條件比較。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「溢洪面汽蝕指標」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"High-speed spillway flow can create local low pressure near surface irregularities. Vapor formation depends on absolute pressure relative to vapor pressure. A cavitation number normalizes available pressure by dynamic pressure, but its critical value depends on geometry, aeration and scale. A value based on mean pressure is therefore a preliminary indicator only. Vapor pressure depends on water temperature and absolute local pressure depends on atmospheric conditions; both should represent the same event rather than unrelated reference conditions. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Spillway cavitation indicator” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，輸入均非本工程操作參數：pabs=85000 Pa; pv=2500 Pa; rho=1000 kg/m3; v=25 m/s; sigma=(pabs-pv)/(0.5*rho*v*v)=0.264。","observationEn":"Order-of-magnitude cue: Original hypothetical example; inputs are not operating parameters of this project: pabs=85000 Pa; pv=2500 Pa; rho=1000 kg/m3; v=25 m/s; sigma=(pabs-pv)/(0.5*rho*v*v)=0.264.","failure":"常見誤解：「所有表面可採同一汽蝕數界線」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"One cavitation-number threshold applies to every spillway surface.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「溢洪面汽蝕指標」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Spillway cavitation indicator”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b202-v15-21-k1","title":"溢洪面汽蝕指標","titleEn":"Spillway cavitation indicator","text":"高速溢洪流在不平整表面附近會產生局部低壓，是否形成汽穴要比較局部絕對壓力與水的蒸氣壓。汽蝕數把可用壓力差除以動壓，便於比較流況，但臨界值仍依表面幾何、含氣與尺度而異。","textEn":"High-speed spillway flow can create local low pressure near surface irregularities. Vapor formation depends on absolute pressure relative to vapor pressure.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]},{"id":"b202-v15-21-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：所有表面可採同一汽蝕數界線 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: One cavitation-number threshold applies to every spillway surface. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]}],"quiz":{"question":"關於「溢洪面汽蝕指標」，下列哪一項敘述正確？","questionEn":"Which statement about \"Spillway cavitation indicator\" is correct?","options":["高速溢洪流在不平整表面附近會產生局部低壓，是否形成汽穴要比較局部絕對壓力與水的蒸氣壓。","所有表面可採同一汽蝕數界線","低水頭可藉無限增加流量完全補償"],"optionsEn":["High-speed spillway flow can create local low pressure near surface irregularities.","One cavitation-number threshold applies to every spillway surface.","Any low head can be fully compensated by unlimited discharge."],"answer":0,"explanation":"高速溢洪流在不平整表面附近會產生局部低壓，是否形成汽穴要比較局部絕對壓力與水的蒸氣壓。 其餘選項是常見誤解。","explanationEn":"High-speed spillway flow can create local low pressure near surface irregularities. The other options are common misconceptions."},"unit":6,"unitFacet":"mechanism","order":5,"sequence":33},{"id":"b202-v15-22","title":"溢洪面汽蝕指標：定量估算","titleEn":"Spillway cavitation indicator: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"],"prerequisiteIds":["b202-v15-21"],"objective":"以數值模型估算「溢洪面汽蝕指標」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Spillway cavitation indicator” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，輸入均非本工程操作參數：pabs=85000 Pa; pv=2500 Pa; rho=1000 kg/m3; v=25 m/s; sigma=(pabs-pv)/(0.5*rho*v*v)=0.264。模型邊界：使用局部平均絕對壓力；未給臨界汽蝕數或損傷速率。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical example; inputs are not operating parameters of this project: pabs=85000 Pa; pv=2500 Pa; rho=1000 kg/m3; v=25 m/s; sigma=(pabs-pv)/(0.5*rho*v*v)=0.264. Model boundary: uses local mean absolute pressure; no critical cavitation value or erosion rate is supplied. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：核對壓力感測器是表壓還是絕對壓，並量測水溫以選取蒸氣壓。","observationEn":"How to cross-check: Confirm whether the sensor reports gauge or absolute pressure and measure water temperature for vapor pressure.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b202-v15-22-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，輸入均非本工程操作參數：pabs=85000 Pa; pv=2500 Pa; rho=1000 kg/m3; v=25 m/s; sigma=(pabs-pv)/(0.5*rho*v*v)=0.264。模型邊界：使用局部平均絕對壓力；未給臨界汽蝕數或損傷速率。","textEn":"Original hypothetical example; inputs are not operating parameters of this project: pabs=85000 Pa; pv=2500 Pa; rho=1000 kg/m3; v=25 m/s; sigma=(pabs-pv)/(0.5*rho*v*v)=0.264. Model boundary: uses local mean absolute pressure; no critical cavitation value or erosion rate is supplied.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]},{"id":"b202-v15-22-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]}],"quiz":{"question":"依「溢洪面汽蝕指標」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Spillway cavitation indicator\", which statement holds?","options":["溫漂校正應消除所有壩體季節位移","原創假想算例，輸入均非本工程操作參數：pabs=85000 Pa; pv=2500 Pa; rho=1000 kg/m3; v=25 m/s; sigma=(pabs-pv)/(0.5*rho*v*v)=0.264。","只知道壩高就能決定拱向分力"],"optionsEn":["Thermal drift correction should remove all seasonal movement of the dam.","Original hypothetical example.","Dam height alone determines the arch load share."],"answer":1,"explanation":"原創假想算例，輸入均非本工程操作參數：pabs=85000 Pa; pv=2500 Pa; rho=1000 kg/m3; v=25 m/s; sigma=(pabs-pv)/(0.5*rho*v*v)=0.264。 重算時請保留單位。","explanationEn":"Original hypothetical example; inputs are not operating parameters of this project: pabs=85000 Pa; pv=2500 Pa; rho=1000 kg/m3; v=25 m/s; sigma=(pabs-pv)/(0.5*rho*v*v)=0.264. Keep units when recalculating."},"unit":6,"unitFacet":"model","order":6,"sequence":34},{"id":"b202-v15-23","title":"溢洪面汽蝕指標：試驗與驗證","titleEn":"Spillway cavitation indicator: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"],"prerequisiteIds":["b202-v15-22"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「溢洪面汽蝕指標」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Spillway cavitation indicator” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"核對壓力感測器是表壓還是絕對壓，並量測水溫以選取蒸氣壓。將壓力波動、表面缺口及含氣記錄對齊，若平均值平穩但瞬時低壓頻繁，應分析低尾分布，不能以平均汽蝕數排除損傷。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Confirm whether the sensor reports gauge or absolute pressure and measure water temperature for vapor pressure. Align pressure fluctuations with surface defects and aeration observations. Frequent low-pressure excursions require analysis of the lower distribution tail even if the mean cavitation number appears steady. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：在固定壓力下把流速提高兩成，重算指標並說明平方效應，再列出判斷實際損傷還需的粗糙度、含氣與壓力波動證據。","observationEn":"Site practice: Increase velocity by twenty percent at fixed pressure and recompute the indicator, explaining the squared effect. List roughness, aeration and pressure-fluctuation evidence still needed before assessing actual surface damage.","failure":"注意干擾：錯把表壓當絕對壓會嚴重改變指標，表面錯台又可能使局部最低壓遠低於平均值；若只看總流量，就無法區分幾何缺陷與通氣不足的來源。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Confusing gauge with absolute pressure distorts the indicator, while a surface offset can make minimum pressure much lower than its mean. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b202-v15-23-k1","title":"驗證方法","titleEn":"Verification method","text":"核對壓力感測器是表壓還是絕對壓，並量測水溫以選取蒸氣壓。將壓力波動、表面缺口及含氣記錄對齊，若平均值平穩但瞬時低壓頻繁，應分析低尾分布，不能以平均汽蝕數排除損傷。","textEn":"Confirm whether the sensor reports gauge or absolute pressure and measure water temperature for vapor pressure. Align pressure fluctuations with surface defects and aeration observations. Frequent low-pressure excursions require analysis of the lower distribution tail even if the mean cavitation number appears steady.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]},{"id":"b202-v15-23-k2","title":"現場實務","titleEn":"Site practice","text":"在固定壓力下把流速提高兩成，重算指標並說明平方效應，再列出判斷實際損傷還需的粗糙度、含氣與壓力波動證據。","textEn":"Increase velocity by twenty percent at fixed pressure and recompute the indicator, explaining the squared effect. List roughness, aeration and pressure-fluctuation evidence still needed before assessing actual surface damage.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]}],"quiz":{"question":"要驗證「溢洪面汽蝕指標」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Spillway cavitation indicator\"?","options":["只要結構分析模型看起來合理，就可以省略現場量測與試驗。","平均降溫達標就表示沒有梯度風險","核對壓力感測器是表壓還是絕對壓，並量測水溫以選取蒸氣壓。"],"optionsEn":["If the structural model looks reasonable, site measurement and testing can be skipped.","Meeting an average cooling target proves there is no gradient risk.","Confirm whether the sensor reports gauge or absolute pressure and measure water temperature for vapor pressure."],"answer":2,"explanation":"核對壓力感測器是表壓還是絕對壓，並量測水溫以選取蒸氣壓。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Confirm whether the sensor reports gauge or absolute pressure and measure water temperature for vapor pressure. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":6,"unitFacet":"verification","order":7,"sequence":35},{"id":"b202-v15-24","title":"溢洪面汽蝕指標：失效診斷","titleEn":"Spillway cavitation indicator: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"],"prerequisiteIds":["b202-v15-23"],"objective":"從症狀倒推「溢洪面汽蝕指標」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Spillway cavitation indicator” and propose discriminating checks, corrective actions and prevention.","instruction":"錯把表壓當絕對壓會嚴重改變指標，表面錯台又可能使局部最低壓遠低於平均值；若只看總流量，就無法區分幾何缺陷與通氣不足的來源。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Confusing gauge with absolute pressure distorts the indicator, while a surface offset can make minimum pressure much lower than its mean. Total discharge alone cannot distinguish a geometric defect from inadequate air supply as the cause of damage. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：蒸氣壓取決於水溫，而局部絕對壓也受大氣壓影響，兩者均應使用與事件同時的條件比較。","observationEn":"Link to the mechanism: Vapor pressure depends on water temperature and absolute local pressure depends on atmospheric conditions; both should represent the same event rather than unrelated reference conditions.","failure":"誤判風險：若相信「所有表面可採同一汽蝕數界線」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"One cavitation-number threshold applies to every spillway surface.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b202-v15-24-k1","title":"失效模式","titleEn":"Failure mode","text":"錯把表壓當絕對壓會嚴重改變指標，表面錯台又可能使局部最低壓遠低於平均值；若只看總流量，就無法區分幾何缺陷與通氣不足的來源。","textEn":"Confusing gauge with absolute pressure distorts the indicator, while a surface offset can make minimum pressure much lower than its mean. Total discharge alone cannot distinguish a geometric defect from inadequate air supply as the cause of damage.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]},{"id":"b202-v15-24-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]}],"quiz":{"question":"在「溢洪面汽蝕指標」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Spillway cavitation indicator\" shows distress, which diagnosis is most reasonable?","options":["錯把表壓當絕對壓會嚴重改變指標，表面錯台又可能使局部最低壓遠低於平均值；若只看總流量，就無法區分幾何缺陷與通氣不足的來源。","只要結構還沒倒，就代表安全餘裕仍然足夠。","低水頭可藉無限增加流量完全補償"],"optionsEn":["Confusing gauge with absolute pressure distorts the indicator, while a surface offset can make minimum pressure much lower than its mean.","As long as the structure is still standing, its safety margin must still be adequate.","Any low head can be fully compensated by unlimited discharge."],"answer":0,"explanation":"錯把表壓當絕對壓會嚴重改變指標，表面錯台又可能使局部最低壓遠低於平均值；若只看總流量，就無法區分幾何缺陷與通氣不足的來源。 需以量測區分可能原因。","explanationEn":"Confusing gauge with absolute pressure distorts the indicator, while a surface offset can make minimum pressure much lower than its mean. Discriminate candidate causes by measurement."},"unit":6,"unitFacet":"failure","order":8,"sequence":36}],"order":6},{"id":"b202-v15-s4","title":"試驗、量測與監測驗證","titleEn":"Testing, measurement and monitoring","description":"本階段聚焦「低水頭機組出力」與「沉積三角洲前移」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Low head generating output\" and \"Sediment delta advance\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b202-v15-25","title":"低水頭機組出力：機制與系統路徑","titleEn":"Low head generating output: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"],"prerequisiteIds":["b202-v15-24"],"objective":"說明「低水頭機組出力」如何影響胡佛壩的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Low head generating output” governs forces, deformation, flow or signals in “Hoover Dam”, and map the relevant inputs, transfer paths and boundaries.","instruction":"庫水位下降使可用水頭改變，維持同一功率可能需要增加流量，但管路損失和機組運轉範圍限制這種補償。教材先固定流量與效率比較水頭對出力的直接作用，再要求用機組特性曲線檢查效率假設，不能線性外推至所有低水位。 導葉開度與流量的關係隨水頭改變，固定開度不等於固定流量，比較模型時必須明確哪一項受到控制。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「低水頭機組出力」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Falling reservoir level changes available head, and maintaining power may require more discharge. Conveyance losses and the machine operating range limit that compensation. First hold flow and efficiency constant to isolate the direct head effect, then consult machine characteristics; the assumed efficiency cannot be extrapolated to every low-water condition. The relation between guide-vane opening and discharge changes with head; fixed opening is not fixed flow, so the controlled quantity must be stated explicitly. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Low head generating output” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，輸入均非本工程操作參數：rho=1000 kg/m3; g=9.81 m/s2; Q=180 m3/s; H=70 m; eta=0.90 (dimensionless); P=rho*g*Q*H*eta/1e6=111.2454 MW。","observationEn":"Order-of-magnitude cue: Original hypothetical example; inputs are not operating parameters of this project: rho=1000 kg/m3; g=9.81 m/s2; Q=180 m3/s; H=70 m; eta=0.90 (dimensionless); P=rho*g*Q*H*eta/1e6=111.2454 MW.","failure":"常見誤解：「低水頭可藉無限增加流量完全補償」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Any low head can be fully compensated by unlimited discharge.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「低水頭機組出力」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Low head generating output”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b202-v15-25-k1","title":"低水頭機組出力","titleEn":"Low head generating output","text":"庫水位下降使可用水頭改變，維持同一功率可能需要增加流量，但管路損失和機組運轉範圍限制這種補償。教材先固定流量與效率比較水頭對出力的直接作用，再要求用機組特性曲線檢查效率假設，不能線性外推至所有低水位。","textEn":"Falling reservoir level changes available head, and maintaining power may require more discharge. Conveyance losses and the machine operating range limit that compensation.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]},{"id":"b202-v15-25-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：低水頭可藉無限增加流量完全補償 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Any low head can be fully compensated by unlimited discharge. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]}],"quiz":{"question":"關於「低水頭機組出力」，下列哪一項敘述正確？","questionEn":"Which statement about \"Low head generating output\" is correct?","options":["低水頭可藉無限增加流量完全補償","庫水位下降使可用水頭改變，維持同一功率可能需要增加流量，但管路損失和機組運轉範圍限制這種補償。","岸線移動距離就是沉積前緣移動距離"],"optionsEn":["Any low head can be fully compensated by unlimited discharge.","Falling reservoir level changes available head, and maintaining power may require more discharge.","Shoreline movement equals the movement of the sediment front."],"answer":1,"explanation":"庫水位下降使可用水頭改變，維持同一功率可能需要增加流量，但管路損失和機組運轉範圍限制這種補償。 其餘選項是常見誤解。","explanationEn":"Falling reservoir level changes available head, and maintaining power may require more discharge. The other options are common misconceptions."},"unit":7,"unitFacet":"mechanism","order":1,"sequence":37},{"id":"b202-v15-26","title":"低水頭機組出力：定量估算","titleEn":"Low head generating output: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"],"prerequisiteIds":["b202-v15-25"],"objective":"以數值模型估算「低水頭機組出力」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Low head generating output” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，輸入均非本工程操作參數：rho=1000 kg/m3; g=9.81 m/s2; Q=180 m3/s; H=70 m; eta=0.90 (dimensionless); P=rho*g*Q*H*eta/1e6=111.2454 MW。模型邊界：淨水頭已扣引水損失且效率固定；未保證機組在該工況允許運行。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical example; inputs are not operating parameters of this project: rho=1000 kg/m3; g=9.81 m/s2; Q=180 m3/s; H=70 m; eta=0.90 (dimensionless); P=rho*g*Q*H*eta/1e6=111.2454 MW. Model boundary: net head already excludes conveyance loss and efficiency is fixed; operation at this point is not thereby authorized. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：將同步流量、淨水頭與電功率換算成效率，並按導葉開度分類比較，避免把不同工況混成一條趨勢。","observationEn":"How to cross-check: Calculate efficiency from synchronized discharge, net head and terminal power, grouping observations by guide-vane position.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b202-v15-26-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，輸入均非本工程操作參數：rho=1000 kg/m3; g=9.81 m/s2; Q=180 m3/s; H=70 m; eta=0.90 (dimensionless); P=rho*g*Q*H*eta/1e6=111.2454 MW。模型邊界：淨水頭已扣引水損失且效率固定；未保證機組在該工況允許運行。","textEn":"Original hypothetical example; inputs are not operating parameters of this project: rho=1000 kg/m3; g=9.81 m/s2; Q=180 m3/s; H=70 m; eta=0.90 (dimensionless); P=rho*g*Q*H*eta/1e6=111.2454 MW. Model boundary: net head already excludes conveyance loss and efficiency is fixed; operation at this point is not thereby authorized.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]},{"id":"b202-v15-26-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]}],"quiz":{"question":"依「低水頭機組出力」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Low head generating output\", which statement holds?","options":["每增加一台備用設備就多一個獨立備援","只要量得裂縫長度就知道全部揚壓","原創假想算例，輸入均非本工程操作參數：rho=1000 kg/m3; g=9.81 m/s2; Q=180 m3/s; H=70 m; eta=0.90 (dimensionless); P=rho*g*Q*H*eta/1e6=111.2454 MW。"],"optionsEn":["Every additional spare device provides another fully independent backup.","Crack length alone determines the complete uplift pressure distribution.","Original hypothetical example."],"answer":2,"explanation":"原創假想算例，輸入均非本工程操作參數：rho=1000 kg/m3; g=9.81 m/s2; Q=180 m3/s; H=70 m; eta=0.90 (dimensionless); P=rho*g*Q*H*eta/1e6=111.2454 MW。 重算時請保留單位。","explanationEn":"Original hypothetical example; inputs are not operating parameters of this project: rho=1000 kg/m3; g=9.81 m/s2; Q=180 m3/s; H=70 m; eta=0.90 (dimensionless); P=rho*g*Q*H*eta/1e6=111.2454 MW. Keep units when recalculating."},"unit":7,"unitFacet":"model","order":2,"sequence":38},{"id":"b202-v15-27","title":"低水頭機組出力：試驗與驗證","titleEn":"Low head generating output: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"],"prerequisiteIds":["b202-v15-26"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「低水頭機組出力」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Low head generating output” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"將同步流量、淨水頭與電功率換算成效率，並按導葉開度分類比較，避免把不同工況混成一條趨勢。另查振動與壓力脈動，若功率模型符合而脈動增大，仍須研究運轉區域限制。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Calculate efficiency from synchronized discharge, net head and terminal power, grouping observations by guide-vane position. Check vibration and pressure pulsation separately. Agreement with the power equation does not resolve an increasing pulsation level or establish suitability of that operating region. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：以相同效率計算恢復原功率所需流量，再加入與流量平方相關的損失重算，繪出補償效果遞減的原因並列出機組曲線的必要資料。","observationEn":"Site practice: Calculate the discharge needed to restore original power at fixed efficiency, then introduce flow-squared losses. Show why compensation diminishes and list the machine-curve data required to assess the revised point.","failure":"注意干擾：為補償低水頭而增加流量，可能提高損失與不穩定流動，使預期增益落空；若流量計受流態改變影響，也會出現虛假的效率提升，需用獨立量測核對。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Increasing flow to compensate for low head may raise losses and unstable-flow effects enough to defeat the expected gain. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b202-v15-27-k1","title":"驗證方法","titleEn":"Verification method","text":"將同步流量、淨水頭與電功率換算成效率，並按導葉開度分類比較，避免把不同工況混成一條趨勢。另查振動與壓力脈動，若功率模型符合而脈動增大，仍須研究運轉區域限制。","textEn":"Calculate efficiency from synchronized discharge, net head and terminal power, grouping observations by guide-vane position. Check vibration and pressure pulsation separately. Agreement with the power equation does not resolve an increasing pulsation level or establish suitability of that operating region.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]},{"id":"b202-v15-27-k2","title":"現場實務","titleEn":"Site practice","text":"以相同效率計算恢復原功率所需流量，再加入與流量平方相關的損失重算，繪出補償效果遞減的原因並列出機組曲線的必要資料。","textEn":"Calculate the discharge needed to restore original power at fixed efficiency, then introduce flow-squared losses. Show why compensation diminishes and list the machine-curve data required to assess the revised point.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]}],"quiz":{"question":"要驗證「低水頭機組出力」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Low head generating output\"?","options":["將同步流量、淨水頭與電功率換算成效率，並按導葉開度分類比較，避免把不同工況混成一條趨勢。","量測時不必記錄溫度、水頭、水位歷程與施工荷重，因為它們不會影響結果。","自由熱伸長就是受約束接縫閉合量"],"optionsEn":["Calculate efficiency from synchronized discharge, net head and terminal power, grouping observations by guide-vane position.","Temperature, water head, water-level history and construction loads need not be recorded because they cannot affect the result.","Free thermal extension equals closure of a restrained joint."],"answer":0,"explanation":"將同步流量、淨水頭與電功率換算成效率，並按導葉開度分類比較，避免把不同工況混成一條趨勢。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Calculate efficiency from synchronized discharge, net head and terminal power, grouping observations by guide-vane position. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":7,"unitFacet":"verification","order":3,"sequence":39},{"id":"b202-v15-28","title":"低水頭機組出力：失效診斷","titleEn":"Low head generating output: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"],"prerequisiteIds":["b202-v15-27"],"objective":"從症狀倒推「低水頭機組出力」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Low head generating output” and propose discriminating checks, corrective actions and prevention.","instruction":"為補償低水頭而增加流量，可能提高損失與不穩定流動，使預期增益落空；若流量計受流態改變影響，也會出現虛假的效率提升，需用獨立量測核對。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Increasing flow to compensate for low head may raise losses and unstable-flow effects enough to defeat the expected gain. A meter affected by altered flow patterns can also indicate a false efficiency improvement, requiring independent verification. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：導葉開度與流量的關係隨水頭改變，固定開度不等於固定流量，比較模型時必須明確哪一項受到控制。","observationEn":"Link to the mechanism: The relation between guide-vane opening and discharge changes with head; fixed opening is not fixed flow, so the controlled quantity must be stated explicitly.","failure":"誤判風險：若相信「低水頭可藉無限增加流量完全補償」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Any low head can be fully compensated by unlimited discharge.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b202-v15-28-k1","title":"失效模式","titleEn":"Failure mode","text":"為補償低水頭而增加流量，可能提高損失與不穩定流動，使預期增益落空；若流量計受流態改變影響，也會出現虛假的效率提升，需用獨立量測核對。","textEn":"Increasing flow to compensate for low head may raise losses and unstable-flow effects enough to defeat the expected gain. A meter affected by altered flow patterns can also indicate a false efficiency improvement, requiring independent verification.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]},{"id":"b202-v15-28-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]}],"quiz":{"question":"在「低水頭機組出力」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Low head generating output\" shows distress, which diagnosis is most reasonable?","options":["所有異常都來自施工人員失誤，設計與細部不需要檢討。","為補償低水頭而增加流量，可能提高損失與不穩定流動，使預期增益落空；若流量計受流態改變影響，也會出現虛假的效率提升，需用獨立量測核對。","岸線移動距離就是沉積前緣移動距離"],"optionsEn":["Every anomaly is a workmanship error, so design and detailing never need review.","Increasing flow to compensate for low head may raise losses and unstable-flow effects enough to defeat the expected gain.","Shoreline movement equals the movement of the sediment front."],"answer":1,"explanation":"為補償低水頭而增加流量，可能提高損失與不穩定流動，使預期增益落空；若流量計受流態改變影響，也會出現虛假的效率提升，需用獨立量測核對。 需以量測區分可能原因。","explanationEn":"Increasing flow to compensate for low head may raise losses and unstable-flow effects enough to defeat the expected gain. Discriminate candidate causes by measurement."},"unit":7,"unitFacet":"failure","order":4,"sequence":40},{"id":"b202-v15-29","title":"沉積三角洲前移：機制與系統路徑","titleEn":"Sediment delta advance: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"],"prerequisiteIds":["b202-v15-28"],"objective":"說明「沉積三角洲前移」如何影響胡佛壩的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Sediment delta advance” governs forces, deformation, flow or signals in “Hoover Dam”, and map the relevant inputs, transfer paths and boundaries.","instruction":"入庫流速降低使較粗顆粒優先沉降，三角洲前緣位置影響取水與通道幾何。簡化的體積除以橫截面積只能估算平均前移距離，不能描述底坡、粒徑分選及潛流。應把泥砂供給與可容納空間分開，避免把局部淤高等同全庫均勻填滿。 沉積前緣可能沿舊河槽形成狹長分支，使用全庫平均寬度會稀釋這種集中前移，需要保留局部地形。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「沉積三角洲前移」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Deceleration at reservoir entry deposits coarse material preferentially, and delta position affects intake and channel geometry. Deposited volume divided by a representative cross-sectional area estimates mean advance only; it omits bed slope, sorting and density currents. Sediment supply and accommodation space must be distinguished from uniform filling of the reservoir. A depositional front may advance as a narrow lobe along the old channel; reservoir-average width conceals that concentration and should not replace local geometry. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Sediment delta advance” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，輸入均非本工程操作參數：V=240000 m3; B=600 m; h=8 m; dx=V/(B*h)=50 m。","observationEn":"Order-of-magnitude cue: Original hypothetical example; inputs are not operating parameters of this project: V=240000 m3; B=600 m; h=8 m; dx=V/(B*h)=50 m.","failure":"常見誤解：「岸線移動距離就是沉積前緣移動距離」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Shoreline movement equals the movement of the sediment front.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「沉積三角洲前移」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Sediment delta advance”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b202-v15-29-k1","title":"沉積三角洲前移","titleEn":"Sediment delta advance","text":"入庫流速降低使較粗顆粒優先沉降，三角洲前緣位置影響取水與通道幾何。簡化的體積除以橫截面積只能估算平均前移距離，不能描述底坡、粒徑分選及潛流。","textEn":"Deceleration at reservoir entry deposits coarse material preferentially, and delta position affects intake and channel geometry. Deposited volume divided by a representative cross-sectional area estimates mean advance only; it omits bed slope, sorting and density currents.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]},{"id":"b202-v15-29-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：岸線移動距離就是沉積前緣移動距離 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Shoreline movement equals the movement of the sediment front. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]}],"quiz":{"question":"關於「沉積三角洲前移」，下列哪一項敘述正確？","questionEn":"Which statement about \"Sediment delta advance\" is correct?","options":["岸線移動距離就是沉積前緣移動距離","溫漂校正應消除所有壩體季節位移","入庫流速降低使較粗顆粒優先沉降，三角洲前緣位置影響取水與通道幾何。"],"optionsEn":["Shoreline movement equals the movement of the sediment front.","Thermal drift correction should remove all seasonal movement of the dam.","Deceleration at reservoir entry deposits coarse material preferentially, and delta position affects intake and channel geometry."],"answer":2,"explanation":"入庫流速降低使較粗顆粒優先沉降，三角洲前緣位置影響取水與通道幾何。 其餘選項是常見誤解。","explanationEn":"Deceleration at reservoir entry deposits coarse material preferentially, and delta position affects intake and channel geometry. The other options are common misconceptions."},"unit":8,"unitFacet":"mechanism","order":5,"sequence":41},{"id":"b202-v15-30","title":"沉積三角洲前移：定量估算","titleEn":"Sediment delta advance: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"],"prerequisiteIds":["b202-v15-29"],"objective":"以數值模型估算「沉積三角洲前移」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Sediment delta advance” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，輸入均非本工程操作參數：V=240000 m3; B=600 m; h=8 m; dx=V/(B*h)=50 m。模型邊界：假設矩形沉積前緣且全數體積推進前緣；不含壓密及側向擴展。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical example; inputs are not operating parameters of this project: V=240000 m3; B=600 m; h=8 m; dx=V/(B*h)=50 m. Model boundary: rectangular depositional front with all volume advancing that front; excludes consolidation and lateral spreading. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：重複測量同一基準的縱剖面及橫斷面，將前緣位置、頂積層厚度與粒徑一起比較。","observationEn":"How to cross-check: Repeat longitudinal and cross-sectional surveys on one datum, comparing front position, topset thickness and grain size.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b202-v15-30-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，輸入均非本工程操作參數：V=240000 m3; B=600 m; h=8 m; dx=V/(B*h)=50 m。模型邊界：假設矩形沉積前緣且全數體積推進前緣；不含壓密及側向擴展。","textEn":"Original hypothetical example; inputs are not operating parameters of this project: V=240000 m3; B=600 m; h=8 m; dx=V/(B*h)=50 m. Model boundary: rectangular depositional front with all volume advancing that front; excludes consolidation and lateral spreading.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]},{"id":"b202-v15-30-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]}],"quiz":{"question":"依「沉積三角洲前移」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Sediment delta advance\", which statement holds?","options":["原創假想算例，輸入均非本工程操作參數：V=240000 m3; B=600 m; h=8 m; dx=V/(B*h)=50 m。","只知道壩高就能決定拱向分力","平均降溫達標就表示沒有梯度風險"],"optionsEn":["Original hypothetical example; inputs are not operating parameters of this project: V=240000 m3; B=600 m; h=8 m; dx=V/(B*h)=50 m.","Dam height alone determines the arch load share.","Meeting an average cooling target proves there is no gradient risk."],"answer":0,"explanation":"原創假想算例，輸入均非本工程操作參數：V=240000 m3; B=600 m; h=8 m; dx=V/(B*h)=50 m。 重算時請保留單位。","explanationEn":"Original hypothetical example; inputs are not operating parameters of this project: V=240000 m3; B=600 m; h=8 m; dx=V/(B*h)=50 m. Keep units when recalculating."},"unit":8,"unitFacet":"model","order":6,"sequence":42},{"id":"b202-v15-31","title":"沉積三角洲前移：試驗與驗證","titleEn":"Sediment delta advance: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"],"prerequisiteIds":["b202-v15-30"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「沉積三角洲前移」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Sediment delta advance” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"重複測量同一基準的縱剖面及橫斷面，將前緣位置、頂積層厚度與粒徑一起比較。若測得體積增加但前緣未動，應查垂向加積或側向展寬，不能因簡式預測前移便宣稱測量錯誤。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Repeat longitudinal and cross-sectional surveys on one datum, comparing front position, topset thickness and grain size. If volume rises without front advance, investigate vertical aggradation or lateral widening rather than rejecting measurements because the simple translation model predicted movement. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：保持沉積體積不變，分別加倍前緣寬度與厚度，計算前移距離，再規劃足以分辨前移和垂向加積的三條重複測線。","observationEn":"Site practice: Keep deposited volume fixed and separately double front width and thickness. Calculate advance distances, then plan three repeat survey lines that distinguish frontal translation from vertical accumulation.","failure":"注意干擾：只追蹤表面岸線可能漏掉水下前緣逼近取水區；反之，水位變化造成的岸線位移也可能被誤作淤積，應以固定高程下的水下地形辨識。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Tracking only the visible shoreline can miss an underwater front approaching an intake. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b202-v15-31-k1","title":"驗證方法","titleEn":"Verification method","text":"重複測量同一基準的縱剖面及橫斷面，將前緣位置、頂積層厚度與粒徑一起比較。若測得體積增加但前緣未動，應查垂向加積或側向展寬，不能因簡式預測前移便宣稱測量錯誤。","textEn":"Repeat longitudinal and cross-sectional surveys on one datum, comparing front position, topset thickness and grain size. If volume rises without front advance, investigate vertical aggradation or lateral widening rather than rejecting measurements because the simple translation model predicted movement.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]},{"id":"b202-v15-31-k2","title":"現場實務","titleEn":"Site practice","text":"保持沉積體積不變，分別加倍前緣寬度與厚度，計算前移距離，再規劃足以分辨前移和垂向加積的三條重複測線。","textEn":"Keep deposited volume fixed and separately double front width and thickness. Calculate advance distances, then plan three repeat survey lines that distinguish frontal translation from vertical accumulation.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]}],"quiz":{"question":"要驗證「沉積三角洲前移」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Sediment delta advance\"?","options":["沿用另一處水工設施或流域的量測結果，就可視為本工程已完成驗證。","重複測量同一基準的縱剖面及橫斷面，將前緣位置、頂積層厚度與粒徑一起比較。","首波壓升必定是所有暫態最大壓力"],"optionsEn":["Reusing results from another hydraulic structure or catchment counts as verifying this structure.","Repeat longitudinal and cross-sectional surveys on one datum, comparing front position, topset thickness and grain size.","The first pressure rise is always the maximum of the whole transient."],"answer":1,"explanation":"重複測量同一基準的縱剖面及橫斷面，將前緣位置、頂積層厚度與粒徑一起比較。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Repeat longitudinal and cross-sectional surveys on one datum, comparing front position, topset thickness and grain size. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":8,"unitFacet":"verification","order":7,"sequence":43},{"id":"b202-v15-32","title":"沉積三角洲前移：失效診斷","titleEn":"Sediment delta advance: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"],"prerequisiteIds":["b202-v15-31"],"objective":"從症狀倒推「沉積三角洲前移」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Sediment delta advance” and propose discriminating checks, corrective actions and prevention.","instruction":"只追蹤表面岸線可能漏掉水下前緣逼近取水區；反之，水位變化造成的岸線位移也可能被誤作淤積，應以固定高程下的水下地形辨識。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Tracking only the visible shoreline can miss an underwater front approaching an intake. Conversely, level-driven shoreline movement may be mistaken for deposition; submerged topography referenced to a fixed elevation is needed to distinguish them. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：沉積前緣可能沿舊河槽形成狹長分支，使用全庫平均寬度會稀釋這種集中前移，需要保留局部地形。","observationEn":"Link to the mechanism: A depositional front may advance as a narrow lobe along the old channel; reservoir-average width conceals that concentration and should not replace local geometry.","failure":"誤判風險：若相信「岸線移動距離就是沉積前緣移動距離」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Shoreline movement equals the movement of the sediment front.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b202-v15-32-k1","title":"失效模式","titleEn":"Failure mode","text":"只追蹤表面岸線可能漏掉水下前緣逼近取水區；反之，水位變化造成的岸線位移也可能被誤作淤積，應以固定高程下的水下地形辨識。","textEn":"Tracking only the visible shoreline can miss an underwater front approaching an intake. Conversely, level-driven shoreline movement may be mistaken for deposition; submerged topography referenced to a fixed elevation is needed to distinguish them.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]},{"id":"b202-v15-32-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]}],"quiz":{"question":"在「沉積三角洲前移」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Sediment delta advance\" shows distress, which diagnosis is most reasonable?","options":["補一層塗料或放寬允收值，就能解決大多數劣化問題。","溫漂校正應消除所有壩體季節位移","只追蹤表面岸線可能漏掉水下前緣逼近取水區；反之，水位變化造成的岸線位移也可能被誤作淤積，應以固定高程下的水下地形辨識。"],"optionsEn":["Adding a coat of paint or widening the acceptance limits solves most deterioration problems.","Thermal drift correction should remove all seasonal movement of the dam.","Tracking only the visible shoreline can miss an underwater front approaching an intake."],"answer":2,"explanation":"只追蹤表面岸線可能漏掉水下前緣逼近取水區；反之，水位變化造成的岸線位移也可能被誤作淤積，應以固定高程下的水下地形辨識。 需以量測區分可能原因。","explanationEn":"Tracking only the visible shoreline can miss an underwater front approaching an intake. Discriminate candidate causes by measurement."},"unit":8,"unitFacet":"failure","order":8,"sequence":44}],"order":7},{"id":"b202-v15-s5","title":"耐久、維護與工程交接","titleEn":"Durability, maintenance and engineering handoff","description":"本階段聚焦「垂線監測溫漂」與「排水備援共同原因」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Pendulum monitoring thermal drift\" and \"Drainage redundancy common causes\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b202-v15-33","title":"垂線監測溫漂：機制與系統路徑","titleEn":"Pendulum monitoring thermal drift: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"],"prerequisiteIds":["b202-v15-32"],"objective":"說明「垂線監測溫漂」如何影響胡佛壩的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Pendulum monitoring thermal drift” governs forces, deformation, flow or signals in “Hoover Dam”, and map the relevant inputs, transfer paths and boundaries.","instruction":"垂線觀測相對位置時，量測支架與讀數裝置也會受到溫度影響。把已校準的儀器溫度係數乘溫差，可估算需扣除的儀器漂移，但不能順便移除壩體真正熱變形。兩種效應必須以獨立基準、內部溫度與不同原理位移儀共同辨識。 溫漂係數具有量測軸向與安裝條件，儀器移位或更換支架後須重新檢查，不能沿用舊校準而未記錄。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「垂線監測溫漂」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Pendulum observations include temperature effects in mounting and readout hardware as well as movement of the structure. A calibrated instrument coefficient estimates instrumental drift, but must not remove genuine thermal deformation of the dam. Independent reference control, internal temperature and another displacement principle are needed to separate the effects. A drift coefficient belongs to a measurement axis and mounting arrangement; relocation or replacement of the support requires renewed checks and documented calibration continuity. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Pendulum monitoring thermal drift” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，輸入均非本工程操作參數：yraw=4.8 mm; k=0.04 mm/K; dT=15 K; ycorr=yraw-k*dT=4.2 mm。","observationEn":"Order-of-magnitude cue: Original hypothetical example; inputs are not operating parameters of this project: yraw=4.8 mm; k=0.04 mm/K; dT=15 K; ycorr=yraw-k*dT=4.2 mm.","failure":"常見誤解：「溫漂校正應消除所有壩體季節位移」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Thermal drift correction should remove all seasonal movement of the dam.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「垂線監測溫漂」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Pendulum monitoring thermal drift”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b202-v15-33-k1","title":"垂線監測溫漂","titleEn":"Pendulum monitoring thermal drift","text":"垂線觀測相對位置時，量測支架與讀數裝置也會受到溫度影響。把已校準的儀器溫度係數乘溫差，可估算需扣除的儀器漂移，但不能順便移除壩體真正熱變形。","textEn":"Pendulum observations include temperature effects in mounting and readout hardware as well as movement of the structure. A calibrated instrument coefficient estimates instrumental drift, but must not remove genuine thermal deformation of the dam.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]},{"id":"b202-v15-33-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：溫漂校正應消除所有壩體季節位移 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Thermal drift correction should remove all seasonal movement of the dam. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]}],"quiz":{"question":"關於「垂線監測溫漂」，下列哪一項敘述正確？","questionEn":"Which statement about \"Pendulum monitoring thermal drift\" is correct?","options":["垂線觀測相對位置時，量測支架與讀數裝置也會受到溫度影響。","溫漂校正應消除所有壩體季節位移","每增加一台備用設備就多一個獨立備援"],"optionsEn":["Pendulum observations include temperature effects in mounting and readout hardware as well as movement of the structure.","Thermal drift correction should remove all seasonal movement of the dam.","Every additional spare device provides another fully independent backup."],"answer":0,"explanation":"垂線觀測相對位置時，量測支架與讀數裝置也會受到溫度影響。 其餘選項是常見誤解。","explanationEn":"Pendulum observations include temperature effects in mounting and readout hardware as well as movement of the structure. The other options are common misconceptions."},"unit":9,"unitFacet":"mechanism","order":1,"sequence":45},{"id":"b202-v15-34","title":"垂線監測溫漂：定量估算","titleEn":"Pendulum monitoring thermal drift: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"],"prerequisiteIds":["b202-v15-33"],"objective":"以數值模型估算「垂線監測溫漂」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Pendulum monitoring thermal drift” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，輸入均非本工程操作參數：yraw=4.8 mm; k=0.04 mm/K; dT=15 K; ycorr=yraw-k*dT=4.2 mm。模型邊界：儀器漂移係數由獨立校準取得且線性；未扣除壩體物理熱位移。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical example; inputs are not operating parameters of this project: yraw=4.8 mm; k=0.04 mm/K; dT=15 K; ycorr=yraw-k*dT=4.2 mm. Model boundary: instrument drift coefficient comes from independent linear calibration; actual thermal movement of the dam is not removed. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：在儀器不移動的控制條件下校準溫度係數，再用現地獨立測量檢查修正後殘差。","observationEn":"How to cross-check: Calibrate temperature sensitivity under controlled fixed-position conditions, then compare corrected residuals with independent field observations.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b202-v15-34-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，輸入均非本工程操作參數：yraw=4.8 mm; k=0.04 mm/K; dT=15 K; ycorr=yraw-k*dT=4.2 mm。模型邊界：儀器漂移係數由獨立校準取得且線性；未扣除壩體物理熱位移。","textEn":"Original hypothetical example; inputs are not operating parameters of this project: yraw=4.8 mm; k=0.04 mm/K; dT=15 K; ycorr=yraw-k*dT=4.2 mm. Model boundary: instrument drift coefficient comes from independent linear calibration; actual thermal movement of the dam is not removed.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]},{"id":"b202-v15-34-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]}],"quiz":{"question":"依「垂線監測溫漂」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Pendulum monitoring thermal drift\", which statement holds?","options":["只要量得裂縫長度就知道全部揚壓","原創假想算例，輸入均非本工程操作參數：yraw=4.8 mm; k=0.04 mm/K; dT=15 K; ycorr=yraw-k*dT=4.2 mm。","自由熱伸長就是受約束接縫閉合量"],"optionsEn":["Crack length alone determines the complete uplift pressure distribution.","Original hypothetical example; inputs are not operating parameters of this project: yraw=4.8 mm; k=0.04 mm/K; dT=15 K; ycorr=yraw-k*dT=4.2 mm.","Free thermal extension equals closure of a restrained joint."],"answer":1,"explanation":"原創假想算例，輸入均非本工程操作參數：yraw=4.8 mm; k=0.04 mm/K; dT=15 K; ycorr=yraw-k*dT=4.2 mm。 重算時請保留單位。","explanationEn":"Original hypothetical example; inputs are not operating parameters of this project: yraw=4.8 mm; k=0.04 mm/K; dT=15 K; ycorr=yraw-k*dT=4.2 mm. Keep units when recalculating."},"unit":9,"unitFacet":"model","order":2,"sequence":46},{"id":"b202-v15-35","title":"垂線監測溫漂：試驗與驗證","titleEn":"Pendulum monitoring thermal drift: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"],"prerequisiteIds":["b202-v15-34"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「垂線監測溫漂」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Pendulum monitoring thermal drift” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"在儀器不移動的控制條件下校準溫度係數，再用現地獨立測量檢查修正後殘差。若季節訊號在不同原理儀器都出現，不應全部當成儀器漂移；並記錄更換支架前後的零點差。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Calibrate temperature sensitivity under controlled fixed-position conditions, then compare corrected residuals with independent field observations. Seasonal signals shared by different instrument principles should not all be removed as drift. Record zero shifts before and after replacement of mounting components as a separate effect. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：產生同時含壩體季節位移和儀器溫漂的序列，分別用獨立係數及錯誤回歸係數校正，展示兩種方法對異常偵測的不同結果。","observationEn":"Site practice: Generate a series containing structural seasonal movement and instrument thermal drift. Correct it using an independent calibration and an incorrect regression coefficient, then demonstrate how the two approaches alter anomaly detection.","failure":"注意干擾：用壩體量測本身回歸儀器溫度係數，可能把真正結構反應吸收到校正項而掩蓋變化；固定端鬆動則可能造成非線性跳值，線性溫漂公式無法修復。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Regressing instrument sensitivity from dam movement itself can absorb genuine structural behavior into a correction term and conceal changes. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b202-v15-35-k1","title":"驗證方法","titleEn":"Verification method","text":"在儀器不移動的控制條件下校準溫度係數，再用現地獨立測量檢查修正後殘差。若季節訊號在不同原理儀器都出現，不應全部當成儀器漂移；並記錄更換支架前後的零點差。","textEn":"Calibrate temperature sensitivity under controlled fixed-position conditions, then compare corrected residuals with independent field observations. Seasonal signals shared by different instrument principles should not all be removed as drift. Record zero shifts before and after replacement of mounting components as a separate effect.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]},{"id":"b202-v15-35-k2","title":"現場實務","titleEn":"Site practice","text":"產生同時含壩體季節位移和儀器溫漂的序列，分別用獨立係數及錯誤回歸係數校正，展示兩種方法對異常偵測的不同結果。","textEn":"Generate a series containing structural seasonal movement and instrument thermal drift. Correct it using an independent calibration and an incorrect regression coefficient, then demonstrate how the two approaches alter anomaly detection.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]}],"quiz":{"question":"要驗證「垂線監測溫漂」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Pendulum monitoring thermal drift\"?","options":["只看一次讀值或外觀即可判定合格，不需要基準點、參考試體或重複量測。","所有表面可採同一汽蝕數界線","在儀器不移動的控制條件下校準溫度係數，再用現地獨立測量檢查修正後殘差。"],"optionsEn":["A single reading or a visual impression is enough to accept the work; no datum, reference specimen or repeat measurement is needed.","One cavitation-number threshold applies to every spillway surface.","Calibrate temperature sensitivity under controlled fixed-position conditions, then compare corrected residuals with independent field observations."],"answer":2,"explanation":"在儀器不移動的控制條件下校準溫度係數，再用現地獨立測量檢查修正後殘差。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Calibrate temperature sensitivity under controlled fixed-position conditions, then compare corrected residuals with independent field observations. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":9,"unitFacet":"verification","order":3,"sequence":47},{"id":"b202-v15-36","title":"垂線監測溫漂：失效診斷","titleEn":"Pendulum monitoring thermal drift: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"],"prerequisiteIds":["b202-v15-35"],"objective":"從症狀倒推「垂線監測溫漂」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Pendulum monitoring thermal drift” and propose discriminating checks, corrective actions and prevention.","instruction":"用壩體量測本身回歸儀器溫度係數，可能把真正結構反應吸收到校正項而掩蓋變化；固定端鬆動則可能造成非線性跳值，線性溫漂公式無法修復。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Regressing instrument sensitivity from dam movement itself can absorb genuine structural behavior into a correction term and conceal changes. A loose mounting point can cause nonlinear jumps that a linear thermal-drift equation cannot repair. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：溫漂係數具有量測軸向與安裝條件，儀器移位或更換支架後須重新檢查，不能沿用舊校準而未記錄。","observationEn":"Link to the mechanism: A drift coefficient belongs to a measurement axis and mounting arrangement; relocation or replacement of the support requires renewed checks and documented calibration continuity.","failure":"誤判風險：若相信「溫漂校正應消除所有壩體季節位移」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Thermal drift correction should remove all seasonal movement of the dam.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b202-v15-36-k1","title":"失效模式","titleEn":"Failure mode","text":"用壩體量測本身回歸儀器溫度係數，可能把真正結構反應吸收到校正項而掩蓋變化；固定端鬆動則可能造成非線性跳值，線性溫漂公式無法修復。","textEn":"Regressing instrument sensitivity from dam movement itself can absorb genuine structural behavior into a correction term and conceal changes. A loose mounting point can cause nonlinear jumps that a linear thermal-drift equation cannot repair.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]},{"id":"b202-v15-36-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]}],"quiz":{"question":"在「垂線監測溫漂」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Pendulum monitoring thermal drift\" shows distress, which diagnosis is most reasonable?","options":["用壩體量測本身回歸儀器溫度係數，可能把真正結構反應吸收到校正項而掩蓋變化；固定端鬆動則可能造成非線性跳值，線性溫漂公式無法修復。","裂縫或異常只出現一次就可以忽略，不需要記錄或追蹤。","每增加一台備用設備就多一個獨立備援"],"optionsEn":["Regressing instrument sensitivity from dam movement itself can absorb genuine structural behavior into a correction term and conceal changes.","A crack or anomaly that appears only once can be ignored without logging or follow-up.","Every additional spare device provides another fully independent backup."],"answer":0,"explanation":"用壩體量測本身回歸儀器溫度係數，可能把真正結構反應吸收到校正項而掩蓋變化；固定端鬆動則可能造成非線性跳值，線性溫漂公式無法修復。 需以量測區分可能原因。","explanationEn":"Regressing instrument sensitivity from dam movement itself can absorb genuine structural behavior into a correction term and conceal changes. Discriminate candidate causes by measurement."},"unit":9,"unitFacet":"failure","order":4,"sequence":48},{"id":"b202-v15-37","title":"排水備援共同原因：機制與系統路徑","titleEn":"Drainage redundancy common causes: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"],"prerequisiteIds":["b202-v15-36"],"objective":"說明「排水備援共同原因」如何影響胡佛壩的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Drainage redundancy common causes” governs forces, deformation, flow or signals in “Hoover Dam”, and map the relevant inputs, transfer paths and boundaries.","instruction":"備援只有在失效機制足夠獨立時才能降低同時失效機率。兩部泵可能共用電源、進水池或控制器，因此把單機失效機率直接相乘會過度樂觀。教材先建立明示獨立的基準，再加入共同原因事件，強調可靠度數值取決於系統邊界與資料期間。 故障機率須附需求期間與成功功能定義，短時啟動成功與長時持續抽水成功是兩個不同的事件。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「排水備援共同原因」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Redundancy reduces simultaneous failure only when failure mechanisms are sufficiently independent. Two pumps may share power, a sump or controls, making a simple product of individual probabilities optimistic. Establish an explicitly independent baseline before adding a common-cause event, and define the system boundary and observation period for every probability. A probability needs a demand interval and a defined success function; successful starting and sustained pumping throughout a long event are different reliability questions. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Drainage redundancy common causes” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，輸入均非本工程操作參數：pA=0.03 (dimensionless); pB=0.04 (dimensionless); pBoth=pA*pB=0.0012。","observationEn":"Order-of-magnitude cue: Original hypothetical example; inputs are not operating parameters of this project: pA=0.03 (dimensionless); pB=0.04 (dimensionless); pBoth=pA*pB=0.0012.","failure":"常見誤解：「每增加一台備用設備就多一個獨立備援」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Every additional spare device provides another fully independent backup.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「排水備援共同原因」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Drainage redundancy common causes”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b202-v15-37-k1","title":"排水備援共同原因","titleEn":"Drainage redundancy common causes","text":"備援只有在失效機制足夠獨立時才能降低同時失效機率。兩部泵可能共用電源、進水池或控制器，因此把單機失效機率直接相乘會過度樂觀。","textEn":"Redundancy reduces simultaneous failure only when failure mechanisms are sufficiently independent. Two pumps may share power, a sump or controls, making a simple product of individual probabilities optimistic.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]},{"id":"b202-v15-37-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：每增加一台備用設備就多一個獨立備援 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Every additional spare device provides another fully independent backup. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]}],"quiz":{"question":"關於「排水備援共同原因」，下列哪一項敘述正確？","questionEn":"Which statement about \"Drainage redundancy common causes\" is correct?","options":["每增加一台備用設備就多一個獨立備援","備援只有在失效機制足夠獨立時才能降低同時失效機率。","只知道壩高就能決定拱向分力"],"optionsEn":["Every additional spare device provides another fully independent backup.","Redundancy reduces simultaneous failure only when failure mechanisms are sufficiently independent.","Dam height alone determines the arch load share."],"answer":1,"explanation":"備援只有在失效機制足夠獨立時才能降低同時失效機率。 其餘選項是常見誤解。","explanationEn":"Redundancy reduces simultaneous failure only when failure mechanisms are sufficiently independent. The other options are common misconceptions."},"unit":10,"unitFacet":"mechanism","order":5,"sequence":49},{"id":"b202-v15-38","title":"排水備援共同原因：定量估算","titleEn":"Drainage redundancy common causes: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"],"prerequisiteIds":["b202-v15-37"],"objective":"以數值模型估算「排水備援共同原因」的關鍵量，並判斷幾何、水頭、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Drainage redundancy common causes” with a numerical model and judge the direction and size of change when geometry, water head, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，輸入均非本工程操作參數：pA=0.03 (dimensionless); pB=0.04 (dimensionless); pBoth=pA*pB=0.0012。模型邊界：兩泵同一需求期間的失效事件假設獨立；不是現場可靠度或年失效率。 師傅任務：保留單位重算一次，再只改變一個輸入（例如增加 10%），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical example; inputs are not operating parameters of this project: pA=0.03 (dimensionless); pB=0.04 (dimensionless); pBoth=pA*pB=0.0012. Model boundary: independent failure events over the same demand interval; not field reliability or an annual failure rate. Mentor task: redo the calculation keeping units, then change one input (for example by +10%), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：用設備接線圖與管線圖找出共同電源、閥件與吸入口，逐項核對測試是否真正涵蓋切換。","observationEn":"How to cross-check: Trace shared power, valves and suction paths on electrical and hydraulic diagrams, then check whether tests actually exercise transfer.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b202-v15-38-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，輸入均非本工程操作參數：pA=0.03 (dimensionless); pB=0.04 (dimensionless); pBoth=pA*pB=0.0012。模型邊界：兩泵同一需求期間的失效事件假設獨立；不是現場可靠度或年失效率。","textEn":"Original hypothetical example; inputs are not operating parameters of this project: pA=0.03 (dimensionless); pB=0.04 (dimensionless); pBoth=pA*pB=0.0012. Model boundary: independent failure events over the same demand interval; not field reliability or an annual failure rate.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]},{"id":"b202-v15-38-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real structure, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]}],"quiz":{"question":"依「排水備援共同原因」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Drainage redundancy common causes\", which statement holds?","options":["平均降溫達標就表示沒有梯度風險","首波壓升必定是所有暫態最大壓力","原創假想算例，輸入均非本工程操作參數：pA=0.03 (dimensionless); pB=0.04 (dimensionless); pBoth=pA*pB=0.0012。"],"optionsEn":["Meeting an average cooling target proves there is no gradient risk.","The first pressure rise is always the maximum of the whole transient.","Original hypothetical example; inputs are not operating parameters of this project: pA=0.03 (dimensionless); pB=0.04 (dimensionless); pBoth=pA*pB=0.0012."],"answer":2,"explanation":"原創假想算例，輸入均非本工程操作參數：pA=0.03 (dimensionless); pB=0.04 (dimensionless); pBoth=pA*pB=0.0012。 重算時請保留單位。","explanationEn":"Original hypothetical example; inputs are not operating parameters of this project: pA=0.03 (dimensionless); pB=0.04 (dimensionless); pBoth=pA*pB=0.0012. Keep units when recalculating."},"unit":10,"unitFacet":"model","order":6,"sequence":50},{"id":"b202-v15-39","title":"排水備援共同原因：試驗與驗證","titleEn":"Drainage redundancy common causes: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"],"prerequisiteIds":["b202-v15-38"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「排水備援共同原因」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Drainage redundancy common causes” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"用設備接線圖與管線圖找出共同電源、閥件與吸入口，逐項核對測試是否真正涵蓋切換。把無需求時停機與有需求時失效分開統計；若兩泵常在同一事件失效，就不能保留獨立假設。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Trace shared power, valves and suction paths on electrical and hydraulic diagrams, then check whether tests actually exercise transfer. Distinguish planned idle states from failures on demand. Repeated simultaneous failures during one event invalidate the independence assumption used by the simple probability product. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：加入一個共同電源失效事件，畫故障樹並計算條件機率，指出何種改造可切斷共同原因，以及需要哪些需求紀錄才能更新估計。","observationEn":"Site practice: Add a common power-failure event, draw a fault tree and calculate conditional probabilities. Identify a modification that removes the shared cause and the demand records needed to update the estimate.","failure":"注意干擾：淹水可能同時淹沒兩部泵的控制設備，使機械備援失去作用；只測馬達空載啟動不會揭露共同吸入口堵塞，需驗證實際抽排路徑與電力隔離。 只量一次、沒有可追溯的基準，或不記錄溫度、水頭與施工荷重，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Flooding can disable controls for both pumps and defeat mechanical redundancy. A single reading, no traceable datum, or unrecorded temperature, water head and construction loads make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b202-v15-39-k1","title":"驗證方法","titleEn":"Verification method","text":"用設備接線圖與管線圖找出共同電源、閥件與吸入口，逐項核對測試是否真正涵蓋切換。把無需求時停機與有需求時失效分開統計；若兩泵常在同一事件失效，就不能保留獨立假設。","textEn":"Trace shared power, valves and suction paths on electrical and hydraulic diagrams, then check whether tests actually exercise transfer. Distinguish planned idle states from failures on demand. Repeated simultaneous failures during one event invalidate the independence assumption used by the simple probability product.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]},{"id":"b202-v15-39-k2","title":"現場實務","titleEn":"Site practice","text":"加入一個共同電源失效事件，畫故障樹並計算條件機率，指出何種改造可切斷共同原因，以及需要哪些需求紀錄才能更新估計。","textEn":"Add a common power-failure event, draw a fault tree and calculate conditional probabilities. Identify a modification that removes the shared cause and the demand records needed to update the estimate.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]}],"quiz":{"question":"要驗證「排水備援共同原因」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Drainage redundancy common causes\"?","options":["用設備接線圖與管線圖找出共同電源、閥件與吸入口，逐項核對測試是否真正涵蓋切換。","不確定度太難估計，報告中只寫最佳值即可。","低水頭可藉無限增加流量完全補償"],"optionsEn":["Trace shared power, valves and suction paths on electrical and hydraulic diagrams, then check whether tests actually exercise transfer.","Uncertainty is too hard to estimate, so the report may state only the best value.","Any low head can be fully compensated by unlimited discharge."],"answer":0,"explanation":"用設備接線圖與管線圖找出共同電源、閥件與吸入口，逐項核對測試是否真正涵蓋切換。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Trace shared power, valves and suction paths on electrical and hydraulic diagrams, then check whether tests actually exercise transfer. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":10,"unitFacet":"verification","order":7,"sequence":51},{"id":"b202-v15-40","title":"排水備援共同原因：失效診斷","titleEn":"Drainage redundancy common causes: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"],"prerequisiteIds":["b202-v15-39"],"objective":"從症狀倒推「排水備援共同原因」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Drainage redundancy common causes” and propose discriminating checks, corrective actions and prevention.","instruction":"淹水可能同時淹沒兩部泵的控制設備，使機械備援失去作用；只測馬達空載啟動不會揭露共同吸入口堵塞，需驗證實際抽排路徑與電力隔離。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體結構的安全、使用性、耐久或營運。","instructionEn":"Flooding can disable controls for both pumps and defeat mechanical redundancy. Testing unloaded motor starts does not reveal a blocked common intake, so the actual drainage path and electrical separation must be verified together. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-structure safety, serviceability, durability or operation.","observation":"連結機制：故障機率須附需求期間與成功功能定義，短時啟動成功與長時持續抽水成功是兩個不同的事件。","observationEn":"Link to the mechanism: A probability needs a demand interval and a defined success function; successful starting and sustained pumping throughout a long event are different reliability questions.","failure":"誤判風險：若相信「每增加一台備用設備就多一個獨立備援」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Every additional spare device provides another fully independent backup.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b202-v15-40-k1","title":"失效模式","titleEn":"Failure mode","text":"淹水可能同時淹沒兩部泵的控制設備，使機械備援失去作用；只測馬達空載啟動不會揭露共同吸入口堵塞，需驗證實際抽排路徑與電力隔離。","textEn":"Flooding can disable controls for both pumps and defeat mechanical redundancy. Testing unloaded motor starts does not reveal a blocked common intake, so the actual drainage path and electrical separation must be verified together.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]},{"id":"b202-v15-40-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v6-hoover-dam","v15s-usbr-manuals","v15s-usbr-instruments","v15s-usace-catalog"]}],"quiz":{"question":"在「排水備援共同原因」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Drainage redundancy common causes\" shows distress, which diagnosis is most reasonable?","options":["先更換最貴的構件；只要症狀消失，就代表已找到根因。","淹水可能同時淹沒兩部泵的控制設備，使機械備援失去作用；只測馬達空載啟動不會揭露共同吸入口堵塞，需驗證實際抽排路徑與電力隔離。","只知道壩高就能決定拱向分力"],"optionsEn":["Replace the most expensive component first; if the symptom disappears, the root cause has been found.","Flooding can disable controls for both pumps and defeat mechanical redundancy.","Dam height alone determines the arch load share."],"answer":1,"explanation":"淹水可能同時淹沒兩部泵的控制設備，使機械備援失去作用；只測馬達空載啟動不會揭露共同吸入口堵塞，需驗證實際抽排路徑與電力隔離。 需以量測區分可能原因。","explanationEn":"Flooding can disable controls for both pumps and defeat mechanical redundancy. Discriminate candidate causes by measurement."},"unit":10,"unitFacet":"failure","order":8,"sequence":52}],"order":8}],"title":"胡佛壩","titleEn":"Hoover Dam","summary":"以導流、大體積混凝土、壩基及洩流系統理解大型壩工的工序依賴與證據。","summaryEn":"Understand dependencies and evidence in large-dam engineering through diversion, mass concrete, foundations and water-release systems.","scope":"以公開資料建立的原創教學分解；所有步驟為紙上、數位模型與證據判讀練習。自繪的示意與自設資料必須標示假設；本站未提供現地工程資料，亦不是核准施工、設備操作或水質放行程序。","scopeEn":"Original educational decomposition of public information. Every step is a paper, digital-model or evidence-interpretation exercise. Label assumptions in self-drawn diagrams and invented data; this site does not supply field engineering records or approved construction, operating or water-release procedures.","diagram":{"type":"dam","labels":["河谷與基岩","壩體","進水與壓力管","溢洪道","監測"],"labelsEn":["Canyon and rock","Dam body","Intake and penstocks","Spillways","Monitoring"],"original":true,"notToScale":true},"stepCount":52,"estimatedMinutes":1240,"curriculumVersion":6,"enrichmentVersion":15,"learningTrack":"water","learningSubdiscipline":"water-dams","learningTags":["water","water-dams","water"],"subcategory":"water-dams","subcategoryTitle":"世界水壩與水庫","subcategoryTitleEn":"World dams and reservoirs","v15Architecture":{"architectureFamily":"water-dam","architectureNodes":[["拱座相容與分力","Abutment compatibility and load sharing"],["混凝土冷卻熱量","Concrete cooling heat account"],["壓力鋼管水錘","Penstock water hammer"],["低水頭機組出力","Low head generating output"],["排水備援共同原因","Drainage redundancy common causes"]],"architectureEdges":[[0,1],[1,2],[2,3],[3,4],[4,1]]},"v15Extension":{"stages":5,"steps":40,"workedExample":{"title":"原創假想算例與邊界","titleEn":"Original hypothetical example and boundaries","text":"以下為本課原創情境串接，所有數值是假設，不能視為業主設計圖或操作許可。先完成「拱座相容與分力」的守恆與邊界檢核，再比較「裂縫連通與揚壓」及「混凝土冷卻熱量」的不同控制量。第一組計算為 ka=8 GN/m; kg=12 GN/m; F=100 MN; Fa=F*ka/(ka+kg)=40 MN；第二組為 pu=900 kPa; pd=100 kPa; B=60 m; w=1 m; U=(pu+pd)/2*B*w=30000 kN。學員須保留量綱、資料時間與量測位置，討論誤差如何傳到結果，將第三單元的限制寫入同一張決策表。任何未納入的結構、河道或機組耦合都列為下一階段工作，不由單一得數推論全工程安全。","textEn":"This original sequence connects the first three units using assumed inputs; none is an owner drawing or an operating authorization. First establish conservation and boundaries for Abutment compatibility and load sharing, then compare the controlling variables in Crack connectivity and uplift and Concrete cooling heat account. The first calculation is ka=8 GN/m; kg=12 GN/m; F=100 MN; Fa=F*ka/(ka+kg)=40 MN; the second is pu=900 kPa; pd=100 kPa; B=60 m; w=1 m; U=(pu+pd)/2*B*w=30000 kN. Preserve dimensions, observation times, and measurement locations in the working sheet. Explain how input uncertainty changes each conclusion and include the third unit limitations in the same decision table. Structural, river, and machine interactions omitted by a model remain subsequent work; a single numerical answer cannot demonstrate safety of the complete project.","assumptions":"數值是本課自行設定的教學假設，不代表任何專案的設計值、量測值或規範允許值；改變系統邊界或荷載組合後必須重算。","assumptionsEn":"Inputs are teaching assumptions, not any project's design values, measurements or code allowances; recalculate after changing the system boundary or load combination.","sourceScope":"原創數值練習；來源支援公開原理與工程背景，不宣稱來源提供這組數據。","sourceScopeEn":"Original numerical exercise; sources support public principles and project context, not these numbers."},"focus":"拱重力壩熱力水力與監測交互診斷","focusEn":"Arch gravity dam thermal hydraulic and monitoring diagnosis"}}};
